function about_text() {
    echo "$APP_NAME $APP_VERSION\n$SIGNATURE\n\n$ABOUT_TEXT"
}

# Lista de versiones de ABOUT_TEXT en Markdown: «## version · fecha», viñetas (las de «  *», dentro
# de la anterior) en una sola linea, el tema antes de «:» en negrita y rutas y ficheros como codigo
CHANGES_MD_PY='
import re, sys

VERSION = re.compile(r"^(\d+\.\d+\.\d+) \((.+)\)$")
# Rutas (/opt/..., ~/...) y nombres de fichero: en letra de codigo (no lo de detras de https://)
CODE = re.compile(r"(?<![\w`:/])((?:~/|\./|/)[\w.*<>@+-]+(?:/[\w.*<>@+-]*)*|[\w*<>-]+(?:\.[\w*<>-]+)*"
                  r"\.(?:php|conf|cnf|deb|dmg|sql|zip|gz|desktop|policy|md|py|sh|log|pid|run|sha256)\b)")


def inline(text):
    text = CODE.sub(lambda m: "`%s`" % m.group(1), text)
    # Un punto o una coma del final de la frase queda fuera del codigo
    return re.sub(r"`([^`]*?)([.,;:]+)`", r"`\1`\2", text)


def bullet(text, depth):
    # «Tema: explicacion» o «Tema:» -> el tema en negrita
    m = re.match(r"^([^:«`/]{2,45}):(\s+(.*))?$", text)
    if m:
        text = "**%s:**%s" % (m.group(1), " " + m.group(3) if m.group(3) else "")
        return "  " * depth + "- " + text[:text.index(":**") + 3] + inline(text[text.index(":**") + 3:])
    return "  " * depth + "- " + inline(text)


def convert(plain):
    out, item, depth = [], None, 0

    def flush():
        nonlocal item
        if item is not None:
            out.append(bullet(item, depth))
            item = None

    for line in plain.split("\n"):
        m = VERSION.match(line)
        if m:
            flush()
            if out and out[-1] != "":
                out.append("")
            out.append("## %s · %s" % (m.group(1), m.group(2)))
            out.append("")
        elif line.startswith("- "):
            flush()
            item, depth = line[2:].strip(), 0
        elif line.startswith("  * "):
            flush()
            item, depth = line[4:].strip(), 1
        elif line.strip() and item is not None:
            item += " " + line.strip()
        elif not line.strip():
            flush()
        else:
            flush()
            out.append(inline(line.strip()))
    flush()
    return "\n".join(out).strip() + "\n"


sys.stdout.write(convert(sys.stdin.read()))
'

# Solo la lista de versiones con sus cambios, en Markdown (ventana "Novedades")
function changes_text() {
    echo -e "$ABOUT_TEXT" | sed -n '/^VERSIONES$/,$p' | tail -n +3 | python3 -I -c "$CHANGES_MD_PY"
}

function panel_about() {
    ui_msg "$(about_text)"
}

function panel() {
    offer_command_install

    while true; do
        local options=()

        official_xampp && options+=("apartar" "Apartar el XAMPP oficial de $LINK (necesario para activar versiones)")
        ! official_xampp && ls -d "$APPS_DIR"/XAMPP-oficial-* > /dev/null 2>&1 \
            && options+=("volver" "Volver al XAMPP oficial apartado")

        options+=(
            "activar" "Cambiar la version activa"
            "instalar" "Instalar versiones de PHP"
            "estado" "Ver versiones instaladas"
            "bases" "Bases de datos (ver, cargar, crear y borrar)"
            "desinstalar" "Desinstalar versiones"
        )
        [ -n "$(version_dirs)" ] && options+=("actualizar" "Actualizar versiones de PHP")
        options+=("acerca" "Acerca de (version y cambios)" "salir" "Salir")

        local header="Version activa: "
        local active=$(active_dir)
        if [ -n "$active" ]; then
            header+="XAMPP-$(version_name "$active") (PHP $(php_version "$active"))"
        else
            header+="ninguna"
        fi
        [ "$DRY" -eq 1 ] && header+="\nMODO SIMULACION: no se hace ningun cambio"
        header+="\n\n¿Que quieres hacer?"

        # Firma abajo a la derecha de la cabecera, del ancho de la lista de opciones
        local cols=$(tput cols 2> /dev/null || echo 80)
        local sign_w=72
        (( sign_w > cols - 6 )) && sign_w=$(( cols - 6 ))
        if [ "$UI" == "text" ]; then
            header=$(with_signature "$header" $sign_w)
            header+="\n$(printf '%*s' $(( sign_w - ${#APP_VERSION} - 1 > 0 ? sign_w - ${#APP_VERSION} - 1 : 0 )) "")v$APP_VERSION"
        fi

        local choice
        choice=$(ui_menu "$header" "activar" "${options[@]}") || break

        case "$choice" in
            apartar) panel_set_aside ;;
            volver) panel_restore_official ;;
            instalar) panel_install ;;
            activar) panel_use ;;
            estado) ui_msg "$(status_text)" ;;
            bases) panel_databases ;;
            desinstalar) panel_remove ;;
            actualizar) panel_rebuild ;;
            acerca) panel_about ;;
            salir) break ;;
        esac
    done

    [ "$UI" == "whiptail" ] && clear

    return 0
}

# ===========================================================================
# Linea de comandos
# ===========================================================================

function cli_install() {
    local php="" yes=0 selected="" full branch

    while [ -n "$1" ]; do
        case "$1" in
            --php) php=${2//,/ }; shift 2 ;;
            --si|--yes|-y) yes=1; shift ;;
            *) echo "Opcion desconocida: $1"; return 1 ;;
        esac
    done

    [ -z "$php" ] && echo "Indica las ramas de PHP (o un parche concreto), por ejemplo: nexum instalar --php 7.4,8.4,8.3.10" && return 1

    local releases=$(php_releases) all=""
    for branch in $php; do
        if [[ "$branch" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
            # Un parche concreto (8.3.10): de una rama que se puede instalar y publicado en php.net
            full=$branch
            branch=${full%.*}
            if ! awk -v b="$branch" '$1 == b { f = 1 } END { exit !f }' <<< "$releases"; then
                echo "PHP $branch no esta disponible, se omite $full" && continue
            fi
            [ -n "$all" ] || all=$(php_all_releases)
            if ! awk -v v="$full" '$1 == v { f = 1 } END { exit !f }' <<< "$all"; then
                echo "PHP $full no esta en php.net, se omite" && continue
            fi
        else
            full=$(awk -v b="$branch" '$1 == b {print $2}' <<< "$releases")
        fi
        [ -z "$full" ] && echo "PHP $branch no esta disponible, se omite" && continue
        [ -e "$BASE_DIR/XAMPP-$full" ] && echo "XAMPP-$full ya existe, se omite" && continue
        php_installed_in "$full" > /dev/null && echo "PHP $full ya esta instalada, se omite" && continue
        selected+=" php:$full"
    done

    [ -z "$selected" ] && echo "No hay nada que instalar." && return 0

    echo "Se va a instalar:$selected"

    if [ $yes -ne 1 ]; then
        read -p "¿Continuar? [s/N]: " answer
        [[ "$answer" =~ ^[sSyY]$ ]] || return 0
    fi

    UI=text
    install_plan "$selected"
}

# rehacer|actualizar <version> [--copia]: con --copia, si su MariaDB cambia de rama (empieza con BBDD
# vacias), antes se guardan las de ahora en ~/nexum-backups
function cli_rebuild() {
    local version=$1
    [ "$2" == "--copia" ] && STACK_DB_COPY=1
    local dir=$BASE_DIR/XAMPP-$version

    if [ -z "$version" ] || [ ! -f "$dir/xamppfiles/etc/pvm-stack" ]; then
        echo "XAMPP-$version no existe"

        return 1
    fi
    if ! [[ "$version" =~ ^[0-9]+\.[0-9]+$ ]]; then
        # (7.4.33, 8.0.30 y 8.1.34 sin el parche de seguridad: se rehacen en su carpeta con el)
        if [ "$(php2shell_state "$(php_version "$dir")" "$dir")" == parcheable ] && php2shell_backport "$version" > /dev/null; then
            echo "XAMPP-$version se vuelve a compilar con el parche de seguridad contra PHP2Shell ($PHP2SHELL_DATE)."
            echo "Sus BBDD se conservan."
            UI=text
            install_plan "parchear:$version"
            return
        fi
        echo "XAMPP-$version lleva su version de PHP en el nombre: no se actualiza. Instala la nueva a su lado."

        return 1
    fi

    local full=$(rebuild_version "$dir" "$(php_releases)")
    if [ -z "$full" ]; then
        echo "No se encuentra en php.net la ultima version de la rama de XAMPP-$version"

        return 1
    fi

    # (con alguna pieza dañada no esta al dia, aunque sus versiones sean las ultimas: se rehace)
    local broken=$(stack_broken "$dir/xamppfiles")
    [ -n "$broken" ] && echo "XAMPP-$version: dañado $broken (no está): se rehace"
    if [ "$(stack_fields "$dir")" == "$(stack_versions "$full")" ] && [ -z "$broken" ] && ! php2shell_missing "$dir" "$full"; then
        if [ -t 1 ]; then
            echo -e "\033[1;32mEl paquete XAMPP-$version se encuentra actualizado.\033[0m No hay nada que actualizar."
        else
            echo "El paquete XAMPP-$version se encuentra actualizado. No hay nada que actualizar."
        fi

        return 0
    fi

    UI=text
    install_plan "rehacer:$full"
}

# ===========================================================================
# Componentes: los parches nuevos de todo lo que usa el gestor
# ===========================================================================
# Lo que tiene un parche nuevo publicado: cada version de PHP (su PHP, Apache, MariaDB, ProFTPD, Perl y
# phpMyAdmin, frente a lo ultimo de su rama), las imagenes de Docker que se usan (las MariaDB comunes,
# phpMyAdmin y la base de cada imagen de PHP, frente a su huella en Docker Hub: sin descargar nada), y
# Docker Desktop (frente a la que ofrece su actualizador), los Node de Nexum (frente al ultimo de su rama)
# y Mailpit, cloudflared y Nginx (frente a los que pone esta version del gestor). componentes [--sin-docker]:
#   L|carpeta|componente|instalada|nueva   una version de PHP: se rehace entera con lo ultimo de su rama
#   F|carpeta|motivo                       una version que no se pone al dia sola (parche concreto, XAMPP)
#   K|imagen|para que                      una imagen de Docker con una version nueva en Docker Hub
#   X|programa|instalada|nueva             Node (una por rama), Mailpit, cloudflared o Nginx
#   M|programa|instalada|nueva|descarga    Docker Desktop: se instala a mano (antes, la copia de sus BBDD)
#   N|programa|la de Nexum|la publicada    Mailpit, cloudflared o Nginx publicados mas nuevos que los que
#                                          pone esta version: solo para saberlo (no cuenta ni se instala)
#   E|lo que no se ha podido consultar
#   S|cuantos componentes tienen parche nuevo
function components_check() {
    local dir name full cur new i n=0 names=(PHP Apache MariaDB ProFTPD Perl phpMyAdmin) releases img v
    local a b broken more
    releases=$(php_releases)
    [ -z "$releases" ] && echo "E|php.net (las versiones de PHP)"
    local pinned
    while IFS= read -r dir; do
        [ -n "$dir" ] || continue
        name=$(version_name "$dir")
        [ -f "$dir/xamppfiles/etc/pvm-stack" ] || continue
        cur=$(stack_fields "$dir")
        # (las de ahora, XAMPP-X.Y.Z, llevan su parche en el nombre: no se rehacen, se instala la nueva al
        # lado y se le pasan las BBDD con pasar-version)
        pinned=0
        [[ "$name" =~ ^[0-9]+\.[0-9]+$ ]] || pinned=1
        [ -z "$releases" ] && continue
        full=$(rebuild_version "$dir" "$releases")
        [ -z "$full" ] && { echo "E|la última versión de la rama de XAMPP-$name"; continue; }
        new=$(stack_versions "$full")
        IFS='|' read -r -a a <<< "$cur"
        IFS='|' read -r -a b <<< "$new"
        # (las piezas dañadas, aunque esten en lo ultimo de su rama: la version se rehace con ellas bien)
        broken=" $(stack_broken "$dir/xamppfiles") "
        for i in 0 1 2 3 4 5; do
            if [[ "$broken" == *" ${names[$i]} "* ]]; then
                if [ $pinned -eq 1 ]; then
                    echo "F|$name|${names[$i]} dañado: instala la versión de nuevo a su lado (Instalar versión) y pásale las BBDD"
                else
                    echo "L|$name|${names[$i]}|dañado|$( [ -n "${b[$i]}" ] && [[ "${b[$i]}" != *.x ]] && echo "${b[$i]}" || echo "${a[$i]}")"
                fi
                n=$((n + 1))
                continue
            fi
            # (lo que no se ha podido consultar sale como su rama seguida de .x: no cuenta)
            [ -z "${b[$i]}" ] || [[ "${b[$i]}" == *.x ]] && continue
            if [ "${a[$i]}" != "${b[$i]}" ] && [ "$(printf '%s\n%s\n' "${a[$i]}" "${b[$i]}" | sort -V | tail -1)" == "${b[$i]}" ]; then
                if [ $pinned -eq 1 ]; then
                    echo "F|$name|${names[$i]} ${a[$i]:-?} → ${b[$i]}: instala la nueva a su lado (Instalar versión) y pásale las BBDD"
                else
                    echo "L|$name|${names[$i]}|${a[$i]:-?}|${b[$i]}"
                fi
                n=$((n + 1))
            fi
        done
    done < <(version_dirs)
    if [ "$1" != --sin-docker ] && docker_ready > /dev/null 2>&1; then
        for v in $(docker_pg_versions); do
            docker_image_outdated "postgres:$v" && { echo "K|postgres:$v|la PostgreSQL $v de Docker"; n=$((n + 1)); }
        done
        for v in $(docker_maria_versions); do
            img=mariadb:$v
            docker_image_outdated "$img" && { echo "K|$img|la MariaDB $v común de Docker"; n=$((n + 1)); }
        done
        if dk image inspect "$DOCKER_PMA_IMAGE" > /dev/null 2>&1 && docker_image_outdated "$DOCKER_PMA_IMAGE"; then
            echo "K|$DOCKER_PMA_IMAGE|phpMyAdmin de Docker"
            n=$((n + 1))
        fi
        for v in $DOCKER_PHP_VERSIONS; do
            dk image inspect "nexum-php:$v" > /dev/null 2>&1 || continue
            img=php:$v-apache
            # (o, con WP-CLI puesto en Configuracion > Docker, sin el: al rehacerla lo trae)
            if docker_php_needs_pgsql "$v"; then
                echo "K|$img|la imagen de PHP $v de Docker (nexum-php:$v), para que traiga pgsql"; n=$((n + 1))
            elif docker_php_needs_wp_cli "$v"; then
                echo "K|$img|la imagen de PHP $v de Docker (nexum-php:$v), para que traiga WP-CLI"; n=$((n + 1))
            elif docker_image_outdated "$img"; then
                echo "K|$img|la imagen de PHP $v de Docker (nexum-php:$v)"; n=$((n + 1))
            fi
        done
    fi
    if mailpit_installed && [ "$(mailpit_installed_version)" != "$MAILPIT_VERSION" ]; then
        echo "X|Mailpit|$(mailpit_installed_version)|$MAILPIT_VERSION"
        n=$((n + 1))
    fi
    if tunnel_installed && [ "$(tunnel_installed_version)" != "$TUNNEL_VERSION" ]; then
        echo "X|cloudflared|$(tunnel_installed_version)|$TUNNEL_VERSION"
        n=$((n + 1))
    fi
    if nginx_installed && [ "$(nginx_installed_version)" != "$NGINX_VERSION" ]; then
        echo "X|Nginx|$(nginx_installed_version)|$NGINX_VERSION"
        n=$((n + 1))
    fi
    more=$(docker_desktop_outdated; node_outdated)
    if [ -n "$more" ]; then
        echo "$more"
        n=$((n + $(grep -c '^[XM]|' <<< "$more")))
    fi
    components_upstream
    echo "S|$n"
}

# Docker Desktop: la version instalada frente a la que ofrece su actualizador (su appcast, el de este
# procesador). Se instala a mano, como cualquier aplicacion: M|Docker Desktop|instalada|nueva|descarga.
# E| si no se ha podido consultar
function docker_desktop_outdated() {
    local plist=$DOCKER_APP/Contents/Info.plist cur arch latest
    [ -f "$plist" ] || return 0
    cur=$(/usr/libexec/PlistBuddy -c 'Print :CFBundleShortVersionString' "$plist" 2> /dev/null)
    [[ "$cur" =~ ^[0-9]+(\.[0-9]+)+$ ]] || return 0
    case "$(uname -m)" in arm64) arch=arm64 ;; *) arch=amd64 ;; esac
    latest=$(curl -q --proto =https -fsS --max-time 10 "https://desktop.docker.com/mac/main/$arch/appcast.xml" 2> /dev/null \
        | grep -oE 'sparkle:shortVersionString="[0-9.]+"' | grep -oE '[0-9]+(\.[0-9]+)+' | sort -V | tail -1)
    if [ -z "$latest" ]; then
        echo "E|desktop.docker.com (la versión de Docker Desktop)"
    elif [ "$latest" != "$cur" ] && [ "$(printf '%s\n%s\n' "$cur" "$latest" | sort -V | tail -1)" == "$latest" ]; then
        echo "M|Docker Desktop|$cur|$latest|$DOCKER_DOWNLOAD_URL"
    fi
    return 0
}

# Docker Desktop nuevo (lo que diga docker_desktop_outdated): se instala a mano, pero antes, una copia de
# todas las BBDD de Docker (si no se puede hacer, se dice y no se abre la descarga). Despues, su pagina
# de descarga; al instalarlo, la pestaña Docker avisa si se ha quedado sin las BBDD de algun proyecto
function docker_desktop_update() {
    if docker_ready; then
        docker_backup_all "no se abre la descarga de Docker Desktop" || return 1
    elif [ -n "$(docker_projects)" ]; then
        echo "Docker Desktop no está en marcha: ábrelo para hacer antes la copia de sus BBDD (si no, no se abre su descarga)"
        return 1
    fi
    echo "Docker Desktop $1: instálalo tú, como cualquier aplicación (o con su «Check for updates»)."
    echo "Si al abrirlo no salen tus contenedores ni tus imágenes, no hagas «Reset to factory defaults»: mira en"
    echo "su Settings, General, «Use containerd for pulling and storing images» (al cambiarlo, lo de antes vuelve"
    echo "a verse). Si no vuelven, la pestaña Docker los rehace con su última copia (nexum docker-recuperar)."
    [ "$DRY" -eq 1 ] || /usr/bin/open "$DOCKER_DOWNLOAD_URL"
    return 0
}

# ¿Hay en Docker Hub una version nueva de una imagen que ya esta en este equipo? Compara su huella
# (la de la etiqueta, con una consulta HEAD que no cuenta para los limites de Docker Hub) con la de
# la descargada. Sin la imagen o sin respuesta: no (no se puede saber)
function docker_image_outdated() {
    local img=$1 repo tag token remote local_d
    repo=${img%%:*} tag=${img#*:}
    [[ "$repo" == */* ]] || repo=library/$repo
    local_d=$(dk image inspect --format '{{range .RepoDigests}}{{println .}}{{end}}' "$img" 2> /dev/null | sed -n 's/^[^@]*@//p' | head -1)
    [ -z "$local_d" ] && return 1
    token=$(curl -q --proto =https -fsS --max-time 15 "https://auth.docker.io/token?service=registry.docker.io&scope=repository:$repo:pull" 2> /dev/null \
        | python3 -I -c 'import json, sys; print(json.load(sys.stdin)["token"])' 2> /dev/null) || return 1
    remote=$(curl -q --proto =https -fsSI --max-time 15 -H "Authorization: Bearer $token" \
        -H "Accept: application/vnd.oci.image.index.v1+json, application/vnd.docker.distribution.manifest.list.v2+json, application/vnd.docker.distribution.manifest.v2+json, application/vnd.oci.image.manifest.v1+json" \
        "https://registry-1.docker.io/v2/$repo/manifests/$tag" 2> /dev/null | tr -d '\r' | sed -n 's/^[Dd]ocker-[Cc]ontent-[Dd]igest: *//p' | head -1)
    [[ "$remote" =~ ^sha256:[0-9a-f]{64}$ ]] || return 1
    [ "$remote" != "$local_d" ]
}

# Node de Nexum (los de NODE_DIR, que pone node_install: no los de nvm ni el del sistema): el mas nuevo
# de cada rama frente al ultimo de su rama en nodejs.org (el que instalaria node_install, de su lista de
# sumas). X|Node|instalada|nueva por cada rama con uno nuevo; E| si no se ha podido consultar
function node_outdated() {
    local d v major cur latest base=https://nodejs.org/dist tls=(--proto =https --tlsv1.2)
    declare -A best=()
    [ -d "$NODE_DIR" ] || return 0
    for d in "$NODE_DIR"/v*/; do
        v=$(basename "$d")
        [[ "$v" =~ ^v([0-9]+)\.[0-9]+\.[0-9]+$ ]] && [ -x "$d/bin/node" ] || continue
        major=${BASH_REMATCH[1]} v=${v#v}
        if [ -z "${best[$major]}" ] || [ "$(printf '%s\n%s\n' "${best[$major]}" "$v" | sort -V | tail -1)" == "$v" ]; then
            best[$major]=$v
        fi
    done
    [ -n "$TEST_DIR" ] && [ -n "$LVM_NODE_BASE" ] && { base=$LVM_NODE_BASE; tls=(); }
    for major in "${!best[@]}"; do
        cur=${best[$major]}
        latest=$(curl -q -fsSL "${tls[@]}" --max-time 10 "$base/latest-v$major.x/SHASUMS256.txt" 2> /dev/null \
            | grep -oE "node-v$major\.[0-9]+\.[0-9]+" | head -1)
        latest=${latest#node-v}
        if [ -z "$latest" ]; then
            echo "E|nodejs.org (Node $major)"
        elif [ "$latest" != "$cur" ] && [ "$(printf '%s\n%s\n' "$cur" "$latest" | sort -V | tail -1)" == "$latest" ]; then
            echo "X|Node|$cur|$latest"
        fi
    done
}

# Pone al dia cada rama de Node que diga node_outdated (node_install) y, si ha ido bien, quita de esa rama
# los anteriores que no esten en marcha (los proyectos de Node usan siempre el mas nuevo de su rama)
function node_update() {
    local line f major d fail=0
    while IFS= read -r line; do
        IFS='|' read -r -a f <<< "$line"
        [ "${f[0]}" == X ] || continue
        major=${f[3]%%.*}
        if ! node_install "$major"; then
            fail=1
            continue
        fi
        for d in "$NODE_DIR"/v"$major".*/; do
            d=${d%/}
            [ "$(basename "$d")" == "v${f[3]}" ] && continue
            [[ "$(basename "$d")" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] || continue
            pgrep -f "$d/bin/node" > /dev/null 2>&1 && { echo "Node ${d##*/v} sigue en marcha: se queda hasta que lo pares"; continue; }
            rm -rf "$d" && echo "Quitado el Node anterior (${d##*/v})"
        done
    done < <(node_outdated)
    return $fail
}

# La ultima version publicada de lo que esta version de Nexum pone con una fija (Mailpit, cloudflared, la
# estable de Nginx): la de su ultima publicacion en GitHub (sin la API, que tiene limites: la direccion a
# la que lleva releases/latest) o la lista de descargas de nginx.org. Sin respuesta: nada
function upstream_latest() {
    local url tag
    case $1 in
        Mailpit) url=https://github.com/axllent/mailpit/releases/latest ;;
        cloudflared) url=https://github.com/cloudflare/cloudflared/releases/latest ;;
        Nginx)
            # (la estable: la rama par mas nueva)
            curl -q --proto =https -fsS --max-time 8 https://nginx.org/en/download.html 2> /dev/null \
                | grep -oE 'nginx-1\.[0-9]*[02468]\.[0-9]+\.tar\.gz' | sed -E 's/^nginx-//; s/\.tar\.gz$//' | sort -uV | tail -1
            return 0 ;;
        *) return 1 ;;
    esac
    tag=$(curl -q --proto =https -fsSI --max-time 8 "$url" 2> /dev/null | tr -d '\r' \
        | sed -n 's|^[Ll]ocation: .*/releases/tag/v\{0,1\}||p' | head -1)
    [[ "$tag" =~ ^[0-9]+(\.[0-9]+)+$ ]] && echo "$tag"
    return 0
}

# N|programa|la que pone Nexum|la publicada: de Mailpit, cloudflared y Nginx (solo los instalados), si se ha
# publicado una mas nueva que la que pone esta version de Nexum. Solo para saberlo: no cuenta como parche
# ni se instala (se pone la fijada, comprobada por su huella, hasta que la traiga una version de Nexum).
# Las tres consultas a la vez, como mucho unos segundos
function components_upstream() {
    local tmp prog pinned latest
    tmp=$(mktemp -d "${TMPDIR:-/tmp}/nexum-publicadas.XXXXXX") || return 0
    mailpit_installed && { upstream_latest Mailpit > "$tmp/Mailpit" & }
    tunnel_installed && { upstream_latest cloudflared > "$tmp/cloudflared" & }
    nginx_installed && { upstream_latest Nginx > "$tmp/Nginx" & }
    wait
    for prog in Mailpit cloudflared Nginx; do
        [ -s "$tmp/$prog" ] || continue
        case $prog in Mailpit) pinned=$MAILPIT_VERSION ;; cloudflared) pinned=$TUNNEL_VERSION ;; Nginx) pinned=$NGINX_VERSION ;; esac
        latest=$(head -1 "$tmp/$prog")
        [ -n "$pinned" ] && [ "$latest" != "$pinned" ] && [ "$(printf '%s\n%s\n' "$pinned" "$latest" | sort -V | tail -1)" == "$latest" ] \
            && echo "N|$prog|$pinned|$latest"
    done
    rm -rf "$tmp"
    return 0
}
# stack_broken <carpeta de sus componentes>: las piezas de una pila propia que estan dañadas, con los
# nombres de Componentes (PHP Apache MariaDB ProFTPD Perl phpMyAdmin), en una linea. Nada si todo esta bien.
# Dañada es que falte su programa o, en Linux, que no responda (--version): como la MariaDB que traia uno
# de sus plugins en lugar de MariaDB, hasta la 1.57.29. En el Mac solo se mira que esten (sus programas no
# se han podido probar asi: uno bueno que no respondiera haria compilar la version sin motivo).
# Con alguna dañada, Componentes la ofrece y al actualizarla se rehace (con sus bases de datos)
function stack_broken() {
    local d=$1 run=1 bad=()
    [[ "$OSTYPE" == darwin* ]] && run=0
    # stack_ok <programa> [argumentos]: que este y (en Linux) que responda, sin entrada ni salida
    function stack_ok() {
        [ -x "$d/$1" ] || return 1
        [ $run -eq 1 ] || return 0
        "$d/$1" "${@:2}" < /dev/null > /dev/null 2>&1
    }
    { stack_ok php/bin/php -n -v && stack_ok php/sbin/php-fpm -n -v; } || bad+=(PHP)
    stack_ok apache2/bin/httpd -v || bad+=(Apache)
    { stack_ok mysql/bin/mariadbd --version && stack_ok mysql/bin/mariadb --version \
        && [ -x "$d/mysql/bin/mariadbd-safe" ]; } || bad+=(MariaDB)
    stack_ok proftpd/sbin/proftpd -v || bad+=(ProFTPD)
    stack_ok perl/bin/perl -e 1 || bad+=(Perl)
    [ -f "$d/phpmyadmin/index.php" ] || bad+=(phpMyAdmin)
    unset -f stack_ok
    echo "${bad[*]}"
}
# componentes-actualizar: pone al dia todo lo que diga components_check. Las versiones de PHP se rehacen
# (la de ahora sigue funcionando mientras se compila); las MariaDB comunes, phpMyAdmin y las imagenes de
# PHP se descargan de nuevo y sus contenedores en marcha se rehacen (unos segundos sin servicio: su BBDD
# y su configuracion no cambian); Mailpit y cloudflared se instalan con su version; Node, con node_install;
# Docker Desktop, a mano, tras una copia de sus BBDD (docker_desktop_update). --copia: a cada version que
# se rehace (como actualizar --copia)
# piezas-danadas: para la ventana (Versiones de PHP), D|version|piezas por cada version de pila propia con
# alguna dañada (stack_broken, que en el Mac solo mira que esten). Sin consultar nada de fuera
function gui_broken() {
    local dir b
    while IFS= read -r dir; do
        [ -n "$dir" ] && [ -f "$dir/xamppfiles/etc/pvm-stack" ] || continue
        b=$(stack_broken "$dir/xamppfiles")
        [ -n "$b" ] && echo "D|$(version_name "$dir")|$b"
    done < <(version_dirs)
    return 0
}

function components_update() {
    local out line f cf folders="" imgs="" progs="" desktop="" fail=0 v slug dir running
    [ "$1" == "--copia" ] && STACK_DB_COPY=1
    echo "Buscando parches nuevos..."
    out=$(components_check)
    while IFS= read -r line; do
        IFS='|' read -r -a f <<< "$line"
        case ${f[0]} in
            L) echo "  XAMPP-${f[1]}: ${f[2]} ${f[3]} → ${f[4]}"
               [[ " $folders " == *" ${f[1]} "* ]] || folders+=" ${f[1]}" ;;
            K) echo "  ${f[1]} (${f[2]}): versión nueva en Docker Hub"; imgs+=" ${f[1]}" ;;
            X) echo "  ${f[1]}: ${f[2]} → ${f[3]}"
               [[ " $progs " == *" ${f[1]} "* ]] || progs+=" ${f[1]}" ;;
            M) echo "  ${f[1]}: ${f[2]} → ${f[3]} (se instala a mano)"; desktop=${f[3]} ;;
            N) echo "  (${f[1]} ${f[3]} publicado: Nexum pone el ${f[2]} hasta que lo traiga una versión suya)" ;;
            F) echo "  XAMPP-${f[1]}: ${f[2]}" ;;
            E) echo "  (no se ha podido consultar: ${f[1]})" ;;
        esac
    done <<< "$out"
    if [ -z "$folders$imgs$progs$desktop" ]; then
        echo "Todo está al día: no hay parches nuevos."
        return 0
    fi
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] se actualizaria lo de arriba"; return 0; }
    local steps=()
    [ -n "$desktop" ] && steps+=("Copia de las BBDD de Docker (para Docker Desktop $desktop)")
    for v in $imgs; do
        case $v in
            mariadb:*) steps+=("MariaDB ${v#mariadb:} de Docker") ;;
            postgres:*) steps+=("PostgreSQL ${v#postgres:} de Docker") ;;
            "$DOCKER_PMA_IMAGE") steps+=("phpMyAdmin de Docker") ;;
            php:*) v=${v#php:}; steps+=("Imagen de PHP ${v%-*}") ;;
            *) steps+=("$v") ;;
        esac
    done
    for v in $progs; do steps+=("$v"); done
    for v in $folders; do steps+=("XAMPP-$v"); done
    task_plan "Actualizando los componentes" "${steps[@]}"
    if [ -n "$desktop" ]; then
        task_step
        docker_desktop_update "$desktop" || fail=1
    fi
    for v in $imgs; do
        task_step
        case $v in
            postgres:*)
                v=${v#postgres:}
                echo "PostgreSQL $v de Docker: la imagen nueva y su contenedor de nuevo (sus BBDD no cambian)"
                if dk pull "postgres:$v"; then
                    [ "$(docker_pg_state "$v")" == marcha ] && { docker_pg_up "$v" > /dev/null || fail=1; }
                else
                    fail=1
                fi ;;
            mariadb:*)
                v=${v#mariadb:}
                echo "MariaDB $v común de Docker: la imagen nueva y su contenedor de nuevo (sus BBDD no cambian)"
                # (y, de paso, que se ponga al dia sola al cambiar de parche: MARIADB_AUTO_UPGRADE)
                cf=$DOCKER_DIR/mariadb-$v/compose.yaml
                if dk pull "mariadb:$v" && awk '/^      MARIADB_AUTO_UPGRADE:/ { next } { print } /^      MARIADB_ROOT_PASSWORD: / { print "      MARIADB_AUTO_UPGRADE: \"1\"" }' "$cf" > "$cf.nuevo" \
                        && chmod 600 "$cf.nuevo" && mv -f "$cf.nuevo" "$cf"; then
                    [ -n "$(dk ps -q --filter "name=^$(docker_maria_name "$v")\$" 2> /dev/null)" ] && { docker_maria_up "$v" > /dev/null || fail=1; }
                else
                    fail=1
                fi ;;
            "$DOCKER_PMA_IMAGE")
                echo "phpMyAdmin de Docker: la imagen nueva"
                dk pull "$DOCKER_PMA_IMAGE" || { fail=1; continue; }
                [ "$(docker_web_state)" == marcha ] && { docker_web_up > /dev/null || fail=1; } ;;
            php:*)
                v=${v#php:}; v=${v%-apache}
                echo "Imagen de PHP $v de Docker: de nuevo, con lo último de Docker Hub"
                docker_php_image "$v" --nueva || { echo "No se ha podido rehacer la imagen de PHP $v: sigue con la anterior"; fail=1; continue; }
                for slug in $(docker_projects); do
                    [[ " $(docker_conf "$slug" PHP) " == *" $v "* ]] || continue
                    dir=$DOCKER_DIR/$slug
                    running=$(dk ps --filter "label=com.docker.compose.project=nexum-$slug" --format '{{.Label "com.docker.compose.service"}}' 2> /dev/null)
                    [ -n "$running" ] && { dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d $running > /dev/null || fail=1; }
                done ;;
        esac
    done
    [ -n "$imgs" ] && dk image prune -f > /dev/null 2>&1
    [[ " $progs " == *" Mailpit "* ]] && { task_step; mailpit_install || fail=1; }
    [[ " $progs " == *" cloudflared "* ]] && { task_step; tunnel_install || fail=1; }
    # (Nginx: se compila otra vez, con tu usuario, y si estaba en marcha sigue con el nuevo)
    [[ " $progs " == *" Nginx "* ]] && { task_step; nginx_build_deps && nginx_build || fail=1; }
    [[ " $progs " == *" Node "* ]] && { task_step; node_update || fail=1; }
    for v in $folders; do
        task_step
        echo "XAMPP-$v: se rehace con lo último de su rama (sigue funcionando mientras se compila)"
        ( cli_rebuild "$v" ) || fail=1
    done
    [ $fail -eq 0 ] && echo "Todo al día." || echo "Algo no se ha podido actualizar: mira lo de arriba."
    return $fail
}

# Hasta la 1.57.6 las copias de seguridad iban en ~/lvm-copias: la primera vez se renombra a
# ~/nexum-backups (COPIES_DIR). Solo si es una carpeta tuya (no un enlace) y aun no hay ninguna
# ~/nexum-backups: si estan las dos, no se toca ninguna
function copies_migrate() {
    local old=$HOME/lvm-copias
    [ -d "$old" ] && [ ! -L "$old" ] && [ -O "$old" ] || { copies_sort; return 0; }
    if [ -e "$COPIES_DIR" ] || [ -L "$COPIES_DIR" ]; then
        copies_sort
        return 0
    fi
    mv "$old" "$COPIES_DIR" 2> /dev/null && chmod 700 "$COPIES_DIR" 2> /dev/null
    copies_sort
    return 0
}

# ~/nexum-backups, por carpetas (1.57.51): solo copias, cada clase en la suya
#   bbdd/lampp-8.4/        (XAMPP-8.4 en el Mac) <base>-<fecha>.sql.gz, <base>-antes-de-cargar-…,
#                          <base>-antes-de-copiar-…, mysql-sistema-…, todas-las-bases-….tar.gz
#   bbdd/docker/           las de Docker (docker-<proyecto>-<base>-…, docker-mariadb-…, docker-postgres-…)
#   proyectos/<carpeta>/   antes-de-actualizar-<fecha>/, cache-prod-<fecha>/, wp-config.php-…, parameters.php-…
#   sistema/hosts/, sistema/vhosts/, sistema/lampp-8.4/ (httpd.conf, php.ini… que cambia el programa)
#   xampp-oficial/         (Mac) las BBDD del XAMPP oficial al apartarlo
# copies_in <subcarpeta> [<carpeta de copias>]: la crea (solo tuya; con sudo, como tu usuario, para que
# root no deje en ella carpetas suyas) y la escribe. En simulacion solo la escribe
function copies_in() {
    local d=${2:-$COPIES_DIR}/$1 user=${SUDO_USER:-$USER}
    if [ "$DRY" -eq 1 ]; then
        echo "$d"
        return 0
    fi
    if [ "$(id -u)" -eq 0 ] && [ -n "$user" ] && [ "$user" != root ]; then
        sudo -u "$user" /bin/sh -c 'umask 077; mkdir -p "$1"' sh "$d" || return 1
    else
        ( umask 077; mkdir -p "$d" ) || return 1
    fi
    echo "$d"
}

# copies_dir_of <fichero de ~/nexum-backups>: crea su carpeta (como copies_in)
function copies_dir_of() {
    local rel=${1#"$COPIES_DIR"/}
    copies_in "$(dirname "$rel")" > /dev/null
}

# Lo que habia suelto en ~/nexum-backups (hasta la 1.57.50), a su carpeta. Solo lo que se reconoce, sin
# sobrescribir nada y sin borrar nada; lo que no se puede mover (de root) se queda donde esta. Solo cuando
# ha cambiado algo en ~/nexum-backups desde la ultima vez (la fecha de la carpeta)
COPIES_SORT_PY='
import os, re, sys
base, lists = sys.argv[1:3]
F = r"(\d{8}-\d{6})"
V = r"([0-9][0-9A-Za-z._]*)"
RULES = [
    (r"hosts-" + F, "sistema/hosts/{0}"),
    (r"httpd-vhosts\.conf-" + F, "sistema/vhosts/{0}"),
    (r"httpd-vhosts-de-lampp-.+-" + F + r"\.conf", "sistema/vhosts/{0}"),
    (r"((?:lampp|XAMPP)-" + V + r")-mysql-sistema-" + F + r"\.sql\.gz", "bbdd/{1}/mysql-sistema-{3}.sql.gz"),
    (r"((?:lampp|XAMPP)-" + V + r")-bases-" + F + r"\.tar\.gz", "bbdd/{1}/todas-las-bases-{3}.tar.gz"),
    (r"((?:lampp|XAMPP)-" + V + r")-(.+)-(antes-de-cargar|antes-de-copiar)-" + F + r"\.sql\.gz",
     "bbdd/{1}/{3}-{4}-{5}.sql.gz"),
    (r"((?:lampp|XAMPP)-" + V + r")-(.+)-" + F + r"\.sql\.gz", "bbdd/{1}/{3}-{4}.sql.gz"),
    (r"docker-.+-" + F + r"\.sql\.gz", "bbdd/docker/{0}"),
    (r"((?:lampp|XAMPP)-" + V + r")-(.+)-" + F, "sistema/{1}/{3}-{4}"),
    (r"(wp-config\.php|parameters\.php|parameters\.yml|settings\.inc\.php)-(.+)-" + F, "proyectos/{2}/{1}-{3}"),
    (r"(.+)-antes-de-actualizar-" + F, "proyectos/{1}/antes-de-actualizar-{2}"),
    (r"(.+)-cache-(dev|prod)-" + F, "proyectos/{1}/cache-{2}-{3}"),
    (r"((?:incompleta-)?XAMPP-oficial-" + F + r")", "xampp-oficial/{0}"),
]
NAME = re.compile(r"^[A-Za-z0-9_][A-Za-z0-9 ._-]*$")
moved = 0
for name in sorted(os.listdir(base)):
    path = os.path.join(base, name)
    if os.path.islink(path) or name in ("bbdd", "proyectos", "sistema", "xampp-oficial"):
        continue
    dest = None
    m = re.fullmatch(r"(.+)-registro-" + F + r"-(.+)\.txt", name)
    if m:
        dest = os.path.join(lists, "%s-%s-%s.txt" % m.groups())
    else:
        for rx, to in RULES:
            m = re.fullmatch(rx, name)
            if m and all(NAME.match(g or "x") for g in m.groups()):
                dest = os.path.join(base, to.format(name, *m.groups()))
                break
    if dest is None or os.path.lexists(dest):
        continue
    try:
        os.makedirs(os.path.dirname(dest), mode=0o700, exist_ok=True)
        os.rename(path, dest)
        moved += 1
    except OSError:
        pass
if moved:
    print("Copias de seguridad ordenadas por carpetas en %s: %d" % (base, moved))
'
function copies_sort() {
    local stamp=$LOG_DIR/copias-ordenadas
    [ -d "$COPIES_DIR" ] && [ ! -L "$COPIES_DIR" ] && [ -O "$COPIES_DIR" ] && [ "$(id -u)" -ne 0 ] || return 0
    [ -f "$stamp" ] && [ ! "$COPIES_DIR" -nt "$stamp" ] && return 0
    mkdir -p -m 700 "$LOG_DIR" || return 0
    ( umask 077; python3 -I -c "$COPIES_SORT_PY" "$COPIES_DIR" "$LOG_DIR/listas" < /dev/null > /dev/null 2>&1 )
    touch "$stamp" 2> /dev/null
    return 0
}

# Lo que ocupa (en KB) dicho para personas: 3,4 MB
function copies_size_text() {
    awk -v n="${1:-0}" 'BEGIN {
        split("KB MB GB TB", u); i = 1
        while (n >= 1024 && i < 4) { n /= 1024; i++ }
        s = (i == 1) ? sprintf("%d %s", n, u[i]) : sprintf("%.1f %s", n, u[i])
        gsub(/\./, ",", s); print s
    }'
}

# ¿Hay en ~/nexum-backups carpetas que no son tuyas (copias que hizo root)? Lo de dentro solo se puede
# borrar con sudo
function copies_need_root() {
    [ -d "$COPIES_DIR" ] && [ ! -L "$COPIES_DIR" ] || return 1
    [ -n "$(find "$COPIES_DIR" -mindepth 1 -type d ! -user "$(id -u)" -print 2> /dev/null | head -1)" ]
}

# copias [vaciar]: sin nada, cuantos ficheros hay en ~/nexum-backups y cuanto ocupan. vaciar borra todo
# lo que hay dentro (la carpeta se queda), despues de comprobar que es una carpeta tuya y no un enlace.
# Lo que no se pueda borrar con tu usuario (copias que hizo root en una carpeta suya) se borra con
# sudo, solo dentro de esa carpeta y sin pasar a otros discos. Con --simular no se borra nada
function copies_command() {
    local dir=$COPIES_DIR files kb left
    case "$1" in
        ""|vaciar) ;;
        *) echo "Uso: nexum copias [vaciar]"; return 1 ;;
    esac
    if [ -L "$dir" ] || { [ -e "$dir" ] && [ ! -d "$dir" ]; }; then
        echo "$dir no es una carpeta (es un enlace o un fichero): no se toca"
        return 1
    fi
    if [ ! -d "$dir" ]; then
        echo "No hay copias de seguridad: $dir no existe"
        return 0
    fi
    if [ ! -O "$dir" ]; then
        echo "$dir no es tuya: no se toca"
        return 1
    fi
    files=$(find "$dir" -mindepth 1 -type f 2> /dev/null | wc -l | tr -d ' ')
    kb=$(du -sk "$dir" 2> /dev/null | cut -f1)
    if [ "$1" != vaciar ]; then
        echo "Copias de seguridad en $dir: $files $([ "$files" == 1 ] && echo fichero || echo ficheros), $(copies_size_text "${kb:-0}")"
        return 0
    fi
    if [ -z "$(find "$dir" -mindepth 1 -maxdepth 1 2> /dev/null | head -1)" ]; then
        echo "No hay copias de seguridad que borrar: $dir esta vacia"
        return 0
    fi
    echo "Borrando las copias de seguridad de $dir ($files $([ "$files" == 1 ] && echo fichero || echo ficheros), $(copies_size_text "${kb:-0}"))..."
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] find $dir -xdev -mindepth 1 -delete (la carpeta se queda)"
        return 0
    fi
    # (find -delete no sigue los enlaces: un enlace de dentro se borra, no lo que hay al otro lado)
    find "$dir" -xdev -mindepth 1 -delete 2> /dev/null
    left=$(find "$dir" -mindepth 1 -maxdepth 1 2> /dev/null | head -1)
    if [ -n "$left" ] && [ -n "$SUDO" ]; then
        echo "Algunas copias son de root: se borran con sudo (solo dentro de $dir)"
        # (se vuelve a comprobar justo antes: que sigue siendo tu carpeta y no un enlace)
        if [ -L "$dir" ] || [ ! -d "$dir" ] || [ ! -O "$dir" ]; then
            echo "$dir ha cambiado: no se borra nada mas"
            return 1
        fi
        sudo find "$dir" -xdev -mindepth 1 -delete
        left=$(find "$dir" -mindepth 1 -maxdepth 1 2> /dev/null | head -1)
    fi
    if [ -n "$left" ]; then
        echo "No se ha podido borrar todo: queda, por ejemplo, $left"
        return 1
    fi
    echo "Copias de seguridad borradas ($dir esta vacia)"
}

# copias-ficheros [si|no]: las copias de los ficheros que el programa cambia por su cuenta (el de hosts,
# los vhosts, la configuracion de los proyectos al cargarlos, lo que cambia asegurar), en ~/nexum-backups
# antes de cambiarlos. Es el fichero COPIES_FILES_FLAG: si esta, se guardan; si no (lo de partida), no.
# Sin nada, dice como esta. No pide contraseña
function copies_files_command() {
    case "$1" in
        "")
            if [ -f "$COPIES_FILES_FLAG" ]; then
                echo "Copias de los ficheros que cambia el programa: si (en ~/nexum-backups, antes de cambiarlos)"
            else
                echo "Copias de los ficheros que cambia el programa: no (con nexum copias-ficheros si, se guardan)"
            fi
            ;;
        si)
            if [ "$DRY" -eq 1 ]; then
                echo "  [simulacion] se crearia $COPIES_FILES_FLAG"
                return 0
            fi
            mkdir -p -m 700 "$LOG_DIR" || return 1
            # (un enlace en su lugar no se sigue: se quita y se crea el fichero)
            [ -L "$COPIES_FILES_FLAG" ] && rm -f "$COPIES_FILES_FLAG"
            [ -f "$COPIES_FILES_FLAG" ] || ( umask 077; : > "$COPIES_FILES_FLAG" ) || return 1
            echo "Copias de los ficheros que cambia el programa: si (en ~/nexum-backups, antes de cambiarlos)"
            ;;
        no)
            if [ "$DRY" -eq 1 ]; then
                echo "  [simulacion] se quitaria $COPIES_FILES_FLAG"
                return 0
            fi
            rm -f "$COPIES_FILES_FLAG" || return 1
            echo "Copias de los ficheros que cambia el programa: no"
            ;;
        *) echo "Uso: nexum copias-ficheros [si|no]"; return 1 ;;
    esac
}
# Limpieza (1.57.9): lo que el programa va dejando y se puede borrar (limpieza, gui-limpieza, limpiar
# <clave>...) y las cachés y registros de un proyecto (gui-limpiar-proyecto, limpiar-proyecto). Todo se
# mide y se borra con CLEAN_PY: sin seguir enlaces, solo dentro de su carpeta y sin pasar a otro disco.
# Lo que es de root, con sudo y con el mismo CLEAN_PY. Sin copias de seguridad: lo borrado no se recupera.
# Las claves, en el orden de la ventana
CLEAN_KEYS=(descargas copias correo registros registros-versiones caches-proyectos temporales sesiones)
CLEAN_PROJECT_KEYS=(cache registros actualizaciones)
# Los temporales, solo si llevan un dia sin cambiar (ellos y lo que tienen dentro)
CLEAN_AGE=86400

# Lo que ocupa (en bytes) dicho para personas: 3,4 MB
function clean_size_text() {
    awk -v n="${1:-0}" 'BEGIN {
        split("B KB MB GB TB", u); i = 1
        while (n >= 1024 && i < 5) { n /= 1024; i++ }
        s = (i == 1) ? sprintf("%d %s", n, u[i]) : sprintf("%.1f %s", n, u[i])
        gsub(/\./, ",", s); print s
    }'
}

function clean_files_text() {
    [ "${1:-0}" == 1 ] && echo "1 fichero" || echo "${1:-0} ficheros"
}

function clean_title() {
    case $1 in
        descargas) echo "Caché de descargas" ;;
        copias) echo "Copias de seguridad" ;;
        correo) echo "Correo de pruebas (Mailpit)" ;;
        registros) echo "Registros del programa" ;;
        registros-versiones) echo "Registros de las versiones" ;;
        caches-proyectos) echo "Cachés de los proyectos" ;;
        temporales) echo "Temporales" ;;
        sesiones) echo "Sesiones de PHP" ;;
        cache) echo "Caché" ;;
        actualizaciones) echo "Restos de actualizaciones" ;;
    esac
}

# El de una clave de un proyecto («Registros de <carpeta>», no los del programa)
function clean_project_title() {
    case $2 in
        registros) echo "Registros de $1" ;;
        *) echo "$(clean_title "$2") de $1" ;;
    esac
}

# Las carpetas de los proyectos de htdocs (sin enlaces, con un nombre valido)
function clean_projects() {
    local d n
    for d in "$HTDOCS_DIR"/*/; do
        d=${d%/} n=${d##*/}
        [ -d "$d" ] && [ ! -L "$d" ] && [[ "$n" =~ ^[A-Za-z0-9_][A-Za-z0-9\ ._-]*$ ]] && echo "$n"
    done
}

# clean_project_rules <carpeta> [<clave>...]: las reglas de CLEAN_PY de un proyecto (todas sus claves si
# no se dice ninguna). Solo las de lo que es: WordPress (wp-content y wp-config.php o wp-includes) o
# PrestaShop (sus clases o su PrestaShopBundle). Nada de wp-content/uploads (salvo los registros de
# WooCommerce, wc-logs) ni de img/ de las tiendas
function clean_project_rules() {
    local dir=$HTDOCS_DIR/$1
    shift
    local want=" ${*:-${CLEAN_PROJECT_KEYS[*]}} "
    if [ -d "$dir/wp-content" ] && { [ -f "$dir/wp-config.php" ] || [ -d "$dir/wp-includes" ]; }; then
        if [[ "$want" == *" cache "* ]]; then
            echo "cache|$dir|vaciar|wp-content/cache||"
        fi
        if [[ "$want" == *" registros "* ]]; then
            echo "registros|$dir|ficheros|wp-content|debug.log|"
            echo "registros|$dir|ficheros|wp-content/uploads/wc-logs|*.log|"
        fi
        if [[ "$want" == *" actualizaciones "* ]]; then
            echo "actualizaciones|$dir|vaciar|wp-content/upgrade||"
            echo "actualizaciones|$dir|vaciar|wp-content/upgrade-temp-backup||"
        fi
    fi
    if [ -f "$dir/classes/PrestaShopAutoload.php" ] || [ -d "$dir/src/PrestaShopBundle" ]; then
        # (los index.php que trae PrestaShop en sus carpetas de cache y de registros se quedan)
        if [[ "$want" == *" cache "* ]]; then
            echo "cache|$dir|vaciar|var/cache||"
            echo "cache|$dir|vaciar|cache/smarty/compile||index"
            echo "cache|$dir|vaciar|cache/smarty/cache||index"
            echo "cache|$dir|vaciar|cache/cachefs||index"
        fi
        if [[ "$want" == *" registros "* ]]; then
            echo "registros|$dir|vaciar|var/logs||index"
            echo "registros|$dir|vaciar|log||index"
            echo "registros|$dir|ficheros|modules/*/logs|*.log|"
            echo "registros|$dir|ficheros|modules/*/log|*.log|"
        fi
    fi
}

# clean_rules <clave>: las reglas de CLEAN_PY de una clave de limpiar (descargas, copias y correo, solo
# para medirlas: se limpian con lo suyo)
function clean_rules() {
    local d t p me
    me=$(id -u)
    case $1 in
        descargas) echo "descargas|$DL_CACHE_DIR|entradas|.|"'(?!.*[.]sha256$).+'"|solo=fich" ;;
        copias) echo "copias|$COPIES_DIR|vaciar|||" ;;
        correo) echo "correo|$MAILPIT_DATA|vaciar|||" ;;
        registros)
            # Solo estos (ninguno es un ajuste): los de las instalaciones y lo que dejan las que fallan
            # (pila-<version>-<fecha>), el de install-db, el de los proyectos sin visitas, los de los
            # proyectos de Node, el de la compilacion de la ventana del Mac y el registro de tareas de la
            # ventana (tareas/) y las listas de ficheros de Actualizar proyecto (listas/). Lo que tenga abierto una tarea o un servidor en marcha se deja; ventana.log,
            # que la ventana tiene abierto mientras esta abierta (en modo de añadir), se vacia
            [ -d "$LOG_DIR" ] && [ ! -L "$LOG_DIR" ] && [ -O "$LOG_DIR" ] || return 0
            echo "registros|$LOG_DIR|ficheros|.|instalacion-*.log|uso"
            echo "registros|$LOG_DIR|ficheros|.|install-db.log|uso"
            echo "registros|$LOG_DIR|ficheros|.|docker-reposo.log|uso"
            echo "registros|$LOG_DIR|entradas|.|pila-[A-Za-z0-9._]+-[0-9]{8}-[0-9]{6}|solo=dir,uso"
            echo "registros|$LOG_DIR|ficheros|node/proyectos|*.log|uso"
            echo "registros|$LOG_DIR|ficheros|app|compilar.log|uso"
            echo "registros|$LOG_DIR|ficheros|tareas|*.txt|uso"
            echo "registros|$LOG_DIR|ficheros|listas|*.txt|uso"
            echo "registros|$LOG_DIR|truncar|.|ventana.log|"
            ;;
        registros-versiones)
            # Se vacian (Apache, PHP-FPM y MariaDB los tienen abiertos): los de Apache (logs/*_log, con los
            # de cada vhost y el de errores de PHP), el de PHP-FPM y el .err de MariaDB. Ni los .pid, ni los
            # cgisock, ni nada mas de los datos de MariaDB
            while IFS= read -r d; do
                [ -n "$d" ] || continue
                echo "registros-versiones|$d|truncar|${CLEAN_STACK_SUB}logs|*_log|"
                echo "registros-versiones|$d|truncar|${CLEAN_STACK_SUB}logs|php-fpm.log|"
                echo "registros-versiones|$d|truncar|${CLEAN_STACK_SUB}var/mysql|*.err|"
            done < <(clean_version_dirs)
            ;;
        caches-proyectos)
            while IFS= read -r p; do
                clean_project_rules "$p" cache | sed 's/^cache|/caches-proyectos|/'
            done < <(clean_projects)
            ;;
        temporales)
            # Los del programa que llevan un dia sin cambiar y no estan en uso (un MariaDB temporal en
            # marcha tiene su socket en /tmp/lvm-mysql-XXXX): las carpetas y ficheros lvm-* que crea en la
            # carpeta temporal y, en ~/.nexum, temporal/ (actualizar proyecto), las listas y carpetas
            # de ps-imagenes, los ficheros de mktemp de los vhosts, hosts, correo y BBDD de Docker, y las
            # descargas a medias de Mailpit, cloudflared y Node. No las copias de pasar a Docker
            # (pasar-*): si el paso falla a medias, son la unica copia de su BBDD. Ni lvm-copia.* (Mac): si
            # no se pudo mover a htdocs un proyecto del XAMPP oficial, se queda ahi y se dice
            for t in "${CLEAN_TMP_DIRS[@]}"; do
                echo "temporales|$t|entradas|.|lvm-(seguridad|mysql|conocidos|hosts|progreso|vhosts|vhosts-cert|cert|ca|pma|actualizar|mailpit|xampp|pila|icono|cliente|bash|instalar|gpg|dns|github|gh|direccion)[.-].+|edad=$CLEAN_AGE,uso"
            done
            if [ -d "$LOG_DIR" ] && [ ! -L "$LOG_DIR" ] && [ -O "$LOG_DIR" ]; then
                echo "temporales|$LOG_DIR|vaciar|temporal||edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|.|ps-imagenes-[a-z0-9_]{8}|solo=dir,edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|.|(ps-imagenes-lista|vhosts-docker|hosts-docker|vhost-docker|vhosts-media|vhosts-borrar|hosts-borrar|correo)-[A-Za-z0-9]{6}|solo=fich,edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|.|(docker|copia)-.+-[A-Za-z0-9]{6}([.]sql[.]gz)?|solo=fich,edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|.|mailpit-descarga[.][A-Za-z0-9]{6}|edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|tunel|(abrir|cloudflared-descarga)[.][A-Za-z0-9]{6}|edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|node|descarga[.][A-Za-z0-9]{6}|edad=$CLEAN_AGE,uso"
            fi
            ;;
        sesiones)
            # Las de cada version: los XAMPP las guardan en su temp (session.save_path); las pilas propias
            # no lo cambian y van a la carpeta temporal, donde solo se borran las tuyas
            while IFS= read -r d; do
                [ -n "$d" ] && echo "sesiones|$d|ficheros|${CLEAN_STACK_SUB}temp|sess_*|"
            done < <(clean_version_dirs)
            for t in "${CLEAN_TMP_DIRS[@]}"; do
                echo "sesiones|$t|ficheros|.|sess_*|uid=$me"
            done
            ;;
    esac
}

# Los correos de Mailpit: los que dice su API si esta en marcha o, si no, los de su base (sin cambiarla)
function clean_mail_count() {
    local n=""
    if [ -n "$(mailpit_pid)" ]; then
        n=$(curl -fs --noproxy '*' --max-time 5 "${MAIL_UI_URL}api/v1/messages?limit=1" 2> /dev/null \
            | grep -oE '"total":[0-9]+' | head -1 | cut -d: -f2)
    fi
    if [ -z "$n" ] && [ -f "$MAILPIT_DATA/mailpit.db" ] && [ ! -L "$MAILPIT_DATA/mailpit.db" ]; then
        n=$(python3 -I -c 'import sqlite3, sys
c = sqlite3.connect("file:" + sys.argv[1] + "?mode=ro", uri=True)
print(c.execute("SELECT COUNT(*) FROM mailbox").fetchone()[0])' "$MAILPIT_DATA/mailpit.db" 2> /dev/null)
    fi
    [[ "$n" =~ ^[0-9]+$ ]] && echo "$n" || echo 0
}

# clean_measure <clave>...: L|<clave>|<bytes>|<ficheros>|<1 si hace falta root> de cada una, sin pedir
# contraseña (lo que no se puede leer con tu usuario no cuenta). Correo: sus correos y su carpeta
function clean_measure() {
    local rules=() k line out b f r
    for k in "$@"; do
        while IFS= read -r line; do
            [ -n "$line" ] && rules+=("$line")
        done < <(clean_rules "$k")
    done
    out=""
    [ ${#rules[@]} -gt 0 ] && out=$(python3 -I -c "$CLEAN_PY" medir "${rules[@]}" < /dev/null 2> /dev/null)
    for k in "$@"; do
        line=$(grep -m 1 "^L|$k|" <<< "$out")
        IFS='|' read -r _ _ b f r <<< "${line:-L|$k|0|0|0}"
        case $k in
            correo) f=$(clean_mail_count); [ "$f" -gt 0 ] || b=0; r=0 ;;
            copias) copies_need_root && r=1 ;;
        esac
        echo "L|$k|${b:-0}|${f:-0}|${r:-0}"
    done
}

function clean_valid_key() {
    local k
    for k in "${CLEAN_KEYS[@]}"; do
        [ "$k" == "$1" ] && return 0
    done
    return 1
}

# limpieza: cada cosa que se puede limpiar, con lo que ocupa y cuantos ficheros
function clean_list() {
    local k b f total=0 line
    echo "Lo que se puede limpiar (nexum limpiar <clave>...):"
    while IFS='|' read -r _ k b f _; do
        total=$((total + b))
        if [ "$f" -gt 0 ]; then
            printf '  %-20s %-30s %s · %s\n' "$k" "$(clean_title "$k")" "$(clean_size_text "$b")" "$(clean_files_text "$f")"
        else
            printf '  %-20s %-30s %s\n' "$k" "$(clean_title "$k")" "vacío"
        fi
    done < <(clean_measure "${CLEAN_KEYS[@]}")
    echo "Total: $(clean_size_text "$total"). Lo que se limpia no se puede recuperar (no se hacen copias)."
}

# ¿Hace falta root para limpiar estas claves? (para pedir la contraseña antes de empezar)
function clean_need_root() {
    local k b f r
    [ $# -gt 0 ] || return 1
    while IFS='|' read -r _ k b f r; do
        [ "${f:-0}" -gt 0 ] && [ "$r" == 1 ] && return 0
    done < <(clean_measure "$@" 2> /dev/null)
    return 1
}

# clean_run <clave> <texto> <reglas...>: limpia con CLEAN_PY como tu usuario y, si algo es de root, otra
# vez con sudo (el mismo CLEAN_PY: solo dentro de sus carpetas y sin seguir enlaces). Con --simular, solo
# dice lo que borraria
function clean_run() {
    local key=$1 title=$2 out out2 rc b f n verb=borrados
    shift 2
    [ $# -gt 0 ] || return 0
    [ "$key" == registros-versiones ] && verb=vaciados
    if [ "$DRY" -eq 1 ]; then
        out=$(python3 -I -c "$CLEAN_PY" simular "$@" < /dev/null 2> /dev/null)
        b=$(awk -F'|' '$1 == "L" { s += $3 } END { print s + 0 }' <<< "$out")
        f=$(awk -F'|' '$1 == "L" { s += $4 } END { print s + 0 }' <<< "$out")
        echo "  [simulacion] $title: se $([ "$verb" == vaciados ] && echo vaciarian || echo borrarian) $(clean_files_text "$f") ($(clean_size_text "$b"))"
        return 0
    fi
    out=$(python3 -I -c "$CLEAN_PY" limpiar "$@" < /dev/null 2>&1)
    rc=$?
    if [ $rc -eq 3 ] && [ -n "$SUDO" ]; then
        echo "$title: parte es de root, se limpia con sudo (solo dentro de sus carpetas, sin seguir enlaces)"
        out2=$(sudo python3 -I -c "$CLEAN_PY" limpiar "$@" < /dev/null 2>&1)
        rc=$?
        out=$(grep -v '^Q|' <<< "$out"; echo "$out2")
    fi
    b=$(awk -F'|' '$1 == "L" { s += $3 } END { print s + 0 }' <<< "$out")
    f=$(awk -F'|' '$1 == "L" { s += $4 } END { print s + 0 }' <<< "$out")
    echo "$title: $verb $(clean_files_text "$f") ($(clean_size_text "$b"))"
    n=$(grep '^U|' <<< "$out" | sort -u | grep -c .)
    if [ "$n" -gt 0 ]; then
        echo "  En uso, se deja$([ "$n" -gt 5 ] && echo " (y $((n - 5)) más)"):"
        grep '^U|' <<< "$out" | sort -u | head -5 | cut -d'|' -f3- | sed 's/^/    /'
    fi
    grep -vE '^[LPUQ]\|' <<< "$out" | grep . | head -5 | sed 's/^/  /'
    if [ $rc -ne 0 ]; then
        n=$(grep -c '^Q|' <<< "$out")
        echo "  No se ha podido limpiar todo$([ "$n" -gt 5 ] && echo " ($n sitios)"):"
        grep '^Q|' <<< "$out" | head -5 | cut -d'|' -f3- | sed 's/^/    /'
        return 1
    fi
    return 0
}

# Mailpit: con su API (correo vaciar). Si no esta en marcha, no se puede
function clean_mail() {
    if [ -z "$(mailpit_pid)" ] && [ "$DRY" -eq 0 ]; then
        echo "Correo de pruebas: Mailpit no esta en marcha (va con la version activa): arrancala y vuelve a limpiarlo"
        return 1
    fi
    mail_command vaciar
}

# limpiar <clave>...: limpia esas cosas (lo que esta vacio, nada). Pide sudo solo si alguna lo necesita
function clean_command() {
    local k b f r keys=() rc=0 line
    if [ $# -eq 0 ]; then
        echo "Uso: nexum limpiar <clave>... (claves: ${CLEAN_KEYS[*]}; nexum limpieza dice lo que ocupa cada una)"
        return 1
    fi
    for k in "$@"; do
        clean_valid_key "$k" || { echo "Clave no valida: $k (claves: ${CLEAN_KEYS[*]})"; return 1; }
        [[ " ${keys[*]} " == *" $k "* ]] || keys+=("$k")
    done
    echo "Limpiando (no se puede recuperar: no se hacen copias)..."
    # (lo medido, antes: dentro del bucle, sudo y lo demas no tienen que leer de una tuberia)
    local measured=() projects=() p
    mapfile -t measured < <(clean_measure "${keys[@]}")
    for line in "${measured[@]}"; do
        IFS='|' read -r _ k b f r <<< "$line"
        if [ "${f:-0}" -eq 0 ]; then
            echo "$(clean_title "$k"): nada que limpiar"
            continue
        fi
        case $k in
            descargas) downloads_command vaciar || rc=1 ;;
            copias) copies_command vaciar || rc=1 ;;
            correo) clean_mail || rc=1 ;;
            caches-proyectos)
                mapfile -t projects < <(clean_projects)
                for p in "${projects[@]}"; do
                    clean_project_key "$p" cache quiet || rc=1
                done
                ;;
            *)
                local rules=()
                while IFS= read -r line; do
                    [ -n "$line" ] && rules+=("$line")
                done < <(clean_rules "$k")
                clean_run "$k" "$(clean_title "$k")" "${rules[@]}" < /dev/null || rc=1
                ;;
        esac
    done
    [ $rc -eq 0 ] && echo "Limpieza terminada" || echo "Limpieza terminada, pero algo no se ha podido limpiar: mira lo de arriba"
    return $rc
}

# Lo que se limpiaria de un proyecto, por clave: <clave>|<bytes>|<ficheros>|<root>|<rutas separadas por ,>
function clean_project_measure() {
    local folder=$1 rules=() line out k b f r
    shift
    while IFS= read -r line; do
        [ -n "$line" ] && rules+=("$line")
    done < <(clean_project_rules "$folder" "$@")
    [ ${#rules[@]} -gt 0 ] || return 0
    out=$(python3 -I -c "$CLEAN_PY" medir "${rules[@]}" < /dev/null 2> /dev/null)
    while IFS='|' read -r _ k b f r; do
        [ -n "$k" ] || continue
        echo "$k|$b|$f|$r|$(awk -F'|' -v k="$k" '$1 == "P" && $2 == k { printf "%s%s", (n++ ? "," : ""), $3 }' <<< "$out")"
    done < <(grep '^L|' <<< "$out")
}

# gui-limpiar-proyecto <carpeta>: P|<clave>|<bytes>|<ficheros>|<rutas> de lo que tiene algo
function gui_clean_project() {
    local folder=${1%/} k b f r paths
    valid_project "$folder" > /dev/null || return 1
    while IFS='|' read -r k b f r paths; do
        [ "${f:-0}" -gt 0 ] && echo "P|$k|$b|$f|$paths"
    done < <(clean_project_measure "$folder")
    return 0
}

function clean_project_need_root() {
    local folder=${1%/} k b f r paths
    valid_project "$folder" > /dev/null 2>&1 || return 1
    shift
    while IFS='|' read -r k b f r paths; do
        [ "${f:-0}" -gt 0 ] && [ "$r" == 1 ] && return 0
    done < <(clean_project_measure "$folder" "$@")
    return 1
}

# clean_project_key <carpeta> <clave> [quiet]: limpia esa clave del proyecto. La var/cache de una tienda,
# con ps_clear_cache (vaciar-cache); lo demas, con clean_run. quiet: sin decir nada si no hay nada
function clean_project_key() {
    local folder=$1 key=$2 quiet=$3 rules=() line b f r paths
    IFS='|' read -r _ b f r paths <<< "$(clean_project_measure "$folder" "$key")"
    if [ "${f:-0}" -eq 0 ]; then
        [ -n "$quiet" ] || echo "$(clean_project_title "$folder" "$key"): nada que limpiar"
        return 0
    fi
    while IFS= read -r line; do
        [ -n "$line" ] && rules+=("$line")
    done < <(clean_project_rules "$folder" "$key")
    if [ "$key" == cache ] && [[ ",$paths," == *",var/cache,"* ]]; then
        ps_clear_cache "$folder" || return 1
        local rest=() x
        for x in "${rules[@]}"; do
            [[ "$x" == *"|vaciar|var/cache||" ]] || rest+=("$x")
        done
        rules=("${rest[@]}")
        [ "$paths" == var/cache ] && return 0
    fi
    clean_run "$key" "$(clean_project_title "$folder" "$key")" "${rules[@]}"
}

# limpiar-proyecto <carpeta> [<clave>...]: sus cachés, registros y restos de actualizaciones (sin claves,
# todo lo que tenga). Las carpetas se vacian, no se borran
function clean_project_command() {
    local folder=${1%/} k keys=() rc=0
    valid_project "$folder" || return 1
    shift
    for k in "$@"; do
        [[ " ${CLEAN_PROJECT_KEYS[*]} " == *" $k "* ]] || { echo "Clave no valida: $k (claves: ${CLEAN_PROJECT_KEYS[*]})"; return 1; }
        [[ " ${keys[*]} " == *" $k "* ]] || keys+=("$k")
    done
    [ ${#keys[@]} -gt 0 ] || keys=("${CLEAN_PROJECT_KEYS[@]}")
    if [ -z "$(clean_project_rules "$folder" "${keys[@]}")" ]; then
        echo "No hay cachés ni registros que limpiar en $folder (no es un WordPress ni una tienda PrestaShop)"
        return 0
    fi
    echo "Limpiando $folder (no se puede recuperar: no se hacen copias)..."
    for k in "${keys[@]}"; do
        clean_project_key "$folder" "$k" || rc=1
    done
    return $rc
}

# El manual (manual_command): con Linux o Mac ya elegido, y como se abre un fichero en este sistema
MANUAL_SO=mac
function manual_open() {
    /usr/bin/open "$1"
}
# manual [--ruta] [<capitulo>]: el manual (ayuda/), que va dentro de este mismo script (al final, después
# del exit, en base64: un solo fichero, también al actualizar). Se saca a ~/.nexum/ayuda la
# primera vez y cada vez que cambia (su huella), y se abre en el navegador en <capitulo> (proyectos,
# limpieza…), con Linux o Mac ya elegido. --ruta: solo dice qué abrir (lo abre la ventana).
# El navegador no siempre respeta lo de detrás de # al abrir un fichero: se abre abrir.html, que lleva a
# index.html?so=…#<capitulo>
MANUAL_PY='
import base64, hashlib, io, os, shutil, sys, tarfile, tempfile
script, dest = sys.argv[1], sys.argv[2]
lines, inside = [], False
with open(script, encoding="utf-8") as f:
    for line in f:
        line = line.rstrip("\n")
        if line == ": <<'"'"'NEXUM_MANUAL'"'"'":
            inside = True
        elif inside and line == "NEXUM_MANUAL":
            break
        elif inside:
            lines.append(line)
if not lines:
    sys.exit("Este script no lleva el manual dentro")
data = "".join(lines).encode()
mark = hashlib.sha256(data).hexdigest()
try:
    with open(os.path.join(dest, ".huella")) as f:
        if f.read().strip() == mark:
            sys.exit(0)
except OSError:
    pass
os.umask(0o077)
parent = os.path.dirname(dest)
os.makedirs(parent, mode=0o700, exist_ok=True)
if os.path.islink(dest):
    sys.exit("%s es un enlace: no se toca" % dest)
new = tempfile.mkdtemp(prefix=".ayuda-", dir=parent)
try:
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(data)), mode="r:") as tar:
        for m in tar:
            parts = m.name.split("/")
            # (solo ficheros y carpetas, dentro de la suya: nada de rutas absolutas, .. ni enlaces)
            if m.name.startswith("/") or ".." in parts or not (m.isfile() or m.isdir()):
                sys.exit("El manual trae algo que no se saca: %s" % m.name)
            path = os.path.join(new, *parts)
            if m.isdir():
                os.makedirs(path, mode=0o700, exist_ok=True)
                continue
            os.makedirs(os.path.dirname(path), mode=0o700, exist_ok=True)
            with tar.extractfile(m) as src, open(path, "wb") as out:
                shutil.copyfileobj(src, out)
    with open(os.path.join(new, ".huella"), "w") as f:
        f.write(mark + "\n")
    old = None
    if os.path.isdir(dest):
        old = tempfile.mkdtemp(prefix=".ayuda-vieja-", dir=parent)
        os.rename(dest, os.path.join(old, "ayuda"))
    os.rename(new, dest)
    new = None
    if old:
        shutil.rmtree(old, ignore_errors=True)
finally:
    if new:
        shutil.rmtree(new, ignore_errors=True)
'

function manual_command() {
    local only="" chapter="" dir=$LOG_DIR/ayuda
    [ "$1" == "--ruta" ] && only=1 && shift
    chapter=${1:-}
    if ! [[ "$chapter" =~ ^[a-z][a-z0-9-]{0,40}$ ]]; then
        [ -n "$chapter" ] && echo "Capitulo no valido: $chapter (se abre el principio)"
        chapter=inicio
    fi
    python3 -I -c "$MANUAL_PY" "$SELF" "$dir" || { echo "No se ha podido sacar el manual a $dir"; return 1; }
    ( umask 077
      printf '<!doctype html>\n<meta charset="utf-8">\n<title>Manual de Nexum Dev Stack</title>\n<meta http-equiv="refresh" content="0; url=index.html?so=%s#%s">\n<script>location.replace("index.html?so=%s#%s")</script>\n' \
          "$MANUAL_SO" "$chapter" "$MANUAL_SO" "$chapter" > "$dir/abrir.html" ) || return 1
    if [ -n "$only" ]; then
        echo "$dir/abrir.html"
        return 0
    fi
    echo "Abriendo el manual: $dir/index.html"
    manual_open "$dir/abrir.html"
}
# Limpieza en el Mac: las versiones son las de BASE_DIR, con sus logs, var/mysql y temp en xamppfiles; la carpeta
# temporal, /private/tmp (/tmp es un enlace a ella) y la tuya (TMPDIR, en /var/folders)
CLEAN_STACK_SUB="xamppfiles/"
CLEAN_TMP_DIRS=(/private/tmp)
if [ -n "$TEST_DIR" ]; then
    CLEAN_TMP_DIRS=("$TEST_DIR/tmp")
elif [ -n "${TMPDIR:-}" ] && [ -d "$TMPDIR" ] && [ ! -L "${TMPDIR%/}" ] && [ -O "$TMPDIR" ]; then
    [ "$(cd "$TMPDIR" && pwd -P)" == "/private/tmp" ] || CLEAN_TMP_DIRS+=("${TMPDIR%/}")
fi

function clean_version_dirs() {
    version_dirs
}

if [ "$1" == "--simular" ]; then
    DRY=1
    shift
fi

# (no en --simular, ni en las pruebas, LVM_PRUEBA, ni al pedir solo la version o las novedades, como
# hace el empaquetador: tu carpeta se queda como esta)
case "${1:-}" in
    version|--version|-v|acerca|about|novedades|-h|--help|--ayuda|construir-pila) ;;
    *) [ "$DRY" -eq 0 ] && [ -z "$TEST_DIR" ] && copies_migrate ;;
esac

# Copias de bases, configuraciones de proyectos y registros: solo para tu usuario (en el Mac la
# carpeta personal suele ser 755: cualquier otro usuario del Mac podria leerlas)
for dir in "$COPIES_DIR" "$LOG_DIR"; do
    if [ -d "$dir" ] && [ -O "$dir" ] && [ ! -L "$dir" ]; then
        chmod 700 "$dir" 2> /dev/null
        find "$dir" -maxdepth 4 -type f -user "$(id -u)" -perm +077 -exec chmod go-rwx {} + 2> /dev/null
    fi
done


# ===========================================================================
# phpMyAdmin: actualizar el de una version
# ===========================================================================
# phpMyAdmin que admite cada PHP: la 5.2 (la ultima) desde PHP 7.2.5, la 5.1.4 desde la 7.1.3 y la
# 4.9.11 antes. Los XAMPP traen la 4.9.2, 5.2.0 o 5.2.1, con fallos de seguridad corregidos despues.
function pma_for_php() {
    local php=$1
    if [ "$(printf '%s\n%s\n' 7.2.5 "$php" | vsort | head -1)" == 7.2.5 ]; then
        latest_pma
    elif [ "$(printf '%s\n%s\n' 7.1.3 "$php" | vsort | head -1)" == 7.1.3 ]; then
        echo 5.1.4
    else
        echo 4.9.11
    fi
}

# Huella sha256 del phpMyAdmin <version>: las que pone el gestor van fijadas aqui; otra, la que
# publica phpMyAdmin (del mismo servidor que el fichero: solo protege de descargas a medias)
function pma_sum() {
    case $1 in
        5.2.3) echo 57881348297c4412f86c410547cf76b4d8a236574dd2c6b7d6a2beebe7fc44e3 ;;
        5.1.4) echo 3230cf0e004b6284c70e0cb26064a8666b271749ef54236d035104a972822999 ;;
        4.9.11) echo 2b14737a2220e5ac9d2eaf683df6b56ebaa490d038ee980367cb4db909a57923 ;;
        *) curl -q --proto =https --proto-redir =https -fsSL "https://files.phpmyadmin.net/phpMyAdmin/$1/phpMyAdmin-$1-all-languages.tar.xz.sha256" 2> /dev/null | grep -oE '^[0-9a-f]{64}' ;;
    esac
}

# Version de phpMyAdmin instalada en <carpeta de phpmyadmin> (vacio si no se sabe)
function pma_installed() {
    local v
    v=$(grep -hoE "(VERSION = |PMA_VERSION', )'[0-9.]+'" "$1/libraries/classes/Version.php" \
        "$1/libraries/classes/Config.php" "$1/libraries/Config.php" 2> /dev/null | head -1 | grep -oE "[0-9][0-9.]+")
    [ -z "$v" ] && v=$(grep -rhoE "(VERSION = |PMA_VERSION', )'[0-9.]+'" "$1/libraries" 2> /dev/null | head -1 | grep -oE "[0-9][0-9.]+")
    echo "$v"
}

# actualizar-phpmyadmin <version>: pone el phpMyAdmin mas nuevo que admite su PHP (comprobado con su
# sha256), con la configuracion de antes (config.inc.php) y una clave de cookies nueva si la de
# XAMPP es la de fabrica. El anterior queda en phpmyadmin.anterior.
function update_pma() {
    local FETCH_FRESH=1
    local version=$1 root dir php cur want tmp sum new grp d rc=0
    if [ "$version" == "--todas" ]; then
        for d in $(version_dirs); do
            [ -f "$d/xamppfiles/phpmyadmin/config.inc.php" ] || continue
            update_pma "$(version_name "$d")" || rc=1
        done
        return $rc
    fi
    valid_version_name "$version" && [ -d "$BASE_DIR/XAMPP-$version" ] \
        || { echo "No existe la version $version"; return 1; }
    root="$BASE_DIR/XAMPP-$version/xamppfiles"
    dir=$root/phpmyadmin
    if [ ! -f "$dir/config.inc.php" ]; then
        echo "$version no tiene phpMyAdmin con su configuracion ($dir/config.inc.php)"
        return 1
    fi
    php=$(php_version "$BASE_DIR/XAMPP-$version")
    cur=$(pma_installed "$dir")
    want=$(pma_for_php "$php")
    [[ "$want" =~ ^[0-9]+(\.[0-9]+){1,3}$ ]] || { echo "No se ha podido saber que phpMyAdmin poner"; return 1; }
    if [ -n "$cur" ] && [ "$(printf '%s\n%s\n' "$want" "$cur" | vsort | tail -1)" == "$cur" ]; then
        echo "phpMyAdmin de $version ya esta al dia ($cur, PHP $php)"
        return 0
    fi
    task_plan "Actualizando phpMyAdmin de $version" "Descargar y comprobar phpMyAdmin $want" "Preparar su configuración" "Cambiar la carpeta"
    echo "phpMyAdmin de $version: ${cur:-version antigua} -> $want (PHP $php)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] descarga, comprobacion sha256 y cambio de $dir (el anterior en phpmyadmin.anterior)"
        return 0
    fi
    # Antes de cambiar nada como root: la carpeta de la version tiene que ser de root (y en
    # Linux, /opt tambien), no un enlace que lleve a otro sitio
    if [ -n "$SUDO" ] && { [ -L "$dir" ] || ! trusted_version_dir "$BASE_DIR/XAMPP-$version"; }; then
        echo "No se cambia phpMyAdmin: XAMPP-$version no es de root (nexum asegurar --todas)"
        return 1
    fi
    task_step
    tmp=$(mktemp -d "${TMPDIR:-/tmp}/lvm-pma.XXXXXX") || return 1
    sum=$(pma_sum "$want")
    if ! download "https://files.phpmyadmin.net/phpMyAdmin/$want/phpMyAdmin-$want-all-languages.tar.xz" "$tmp/pma.tar.xz" "$sum" \
            "https://files.phpmyadmin.net/phpMyAdmin/$want/phpMyAdmin-$want-all-languages.tar.xz.asc" PMA \
            || ! tar -xJf "$tmp/pma.tar.xz" -C "$tmp"; then
        rm -rf "$tmp"
        return 1
    fi
    new=$tmp/phpMyAdmin-$want-all-languages
    [ -d "$new" ] || { rm -rf "$tmp"; echo "El paquete de phpMyAdmin no es el esperado"; return 1; }
    # La configuracion de antes; la clave de las cookies de XAMPP es la misma en todos (xampp)
    task_step
    cp "$dir/config.inc.php" "$new/config.inc.php" || { rm -rf "$tmp"; return 1; }
    python3 -I - "$new/config.inc.php" <<'PY'
import re, secrets, string, sys
path = sys.argv[1]
text = open(path, encoding="utf-8", errors="surrogateescape").read()
m = re.search(r"""\$cfg\[\s*['"]blowfish_secret['"]\s*\]\s*=\s*(['"])(.*?)\1""", text)
if m is None or len(m.group(2)) < 32:
    key = "".join(secrets.choice(string.ascii_letters + string.digits) for _ in range(32))
    assign = "$cfg['blowfish_secret'] = '%s'" % key
    if m:
        text = text[:m.start()] + assign + text[m.end():]
    else:
        text = text.rstrip() + "\n" + assign + "; /* lvm-instalador */\n"
    open(path, "w", encoding="utf-8", errors="surrogateescape").write(text)
PY
    grp=$(stat -f %Sg "$dir/tmp" 2> /dev/null || echo root)
    # phpMyAdmin no trae enlaces: uno en la carpeta (que es tuya hasta que root la copia) seria de
    # otro programa. Se mira otra vez en la copia, ya de root, y tmp la crea root vacia (si fuera un
    # enlace, root cambiaria el dueño y los permisos de lo que apunta)
    if [ -n "$(find "$new" \( -type l -o -type f -links +1 \) -print -quit)" ]; then
        rm -rf "$tmp"
        echo "El phpMyAdmin descargado tiene enlaces (no deberia): no se cambia nada"
        return 1
    fi
    task_step
    if ! { $SUDO rm -rf "$root/phpmyadmin.anterior" && $SUDO mv "$dir" "$root/phpmyadmin.anterior"; }; then
        echo "No se ha podido apartar $dir: no se cambia nada"
        rm -rf "$tmp"
        return 1
    fi
    if ! { $SUDO cp -R "$new" "$dir" \
            && [ -z "$($SUDO find "$dir" -type l -print -quit)" ] \
            && $SUDO chown -R root:admin "$dir" \
            && $SUDO chmod -R go-w "$dir" \
            && $SUDO rm -rf "$dir/tmp" \
            && $SUDO install -d -o 0 -g "$grp" -m 775 "$dir/tmp"; }; then
        $SUDO rm -rf "$dir" && $SUDO mv "$root/phpmyadmin.anterior" "$dir"
        echo "No se ha podido cambiar $dir: se ha dejado el phpMyAdmin anterior"
        rm -rf "$tmp"
        return 1
    fi
    rm -rf "$tmp"
    if [ "$(active_dir)" == "$(realpath_f "$BASE_DIR/XAMPP-$version")" ] && service_running apache; then
        run xampp_ctl reloadapache > /dev/null
    fi
    echo "phpMyAdmin $want instalado en $version"
}

# Versiones de antes de la 1.39.3 que siguen en /Applications: el gestor ya no las arranca como root.
# Se avisa (en Terminal; la ventana lo dice en sus avisos) y el panel ofrece pasarlas
if [ -z "$TEST_DIR" ] && [ "$DRY" -eq 0 ] && [[ "$1" != gui-* ]] && [ "$1" != migrar ] && [ "$1" != instalar-gestor ] \
        && [ "$1" != construir-pila ] && [ -t 1 ] && [ -n "$(legacy_dirs)" ]; then
    echo "Aviso: hay versiones en $LEGACY_DIR de antes de la 1.39.3, que el gestor ya no arranca como administrador." >&2
    echo "Pasalas a $BASE_DIR (de root) con: nexum migrar" >&2
    if [ -z "$1" ] && ui_yesno "Las versiones de antes de la 1.39.3 estan en $LEGACY_DIR, donde puede escribir el grupo admin (tu usuario), y ya no se arrancan como administrador.\n\nSe pasan a $BASE_DIR (de root) con sus BBDD, proyectos, vhosts y certificados; en $LEGACY_DIR queda un enlace a cada una. Pide tu contraseña de administrador.\n\n¿Pasarlas ahora?"; then
        gestor_migrate
    fi
fi

# Proyectos de Node (Astro, Next, Nuxt, SvelteKit, Vite...): carpetas de htdocs con su package.json, cada
# una con su propio servidor en 127.0.0.1, siempre con tu usuario (nunca root ni sudo). En Desarrollo, con
# el servidor del proyecto; Compilado, como en produccion: es el unico que se comparte por el tunel, porque
# el proxy no deja pasar ficheros ocultos (/node_modules/.vite) y asi el codigo fuente no sale del equipo.
NODE_DIR=$LOG_DIR/node
NODE_RUN_DIR=$NODE_DIR/proyectos
NODE_DEFAULT_MAJOR=26
NODE_PORT_FROM=4321
NODE_PORT_TO=4399

# P|carpeta|tipo|parado o marcha|modo|direccion|Node que pide (26, o 24+ si vale de ahi en adelante)|
# dependencias instaladas (1/0)|scripts (d de dev, b de build, s de start). Con una carpeta, solo esa.
# No son de Node las webs de PHP que usan npm para sus estilos (wp-config.php, index.php, artisan)
NODE_LIST_PY='
import json, os, re, subprocess, sys
htdocs, run = sys.argv[1:3]
only = sys.argv[3] if len(sys.argv) > 3 else None
KINDS = (("astro", "Astro"), ("next", "Next"), ("nuxt", "Nuxt"), ("@sveltejs/kit", "SvelteKit"), ("vite", "Vite"))


def need(d, pkg):
    for name in (".nvmrc", ".node-version"):
        try:
            with open(os.path.join(d, name), encoding="utf-8") as f:
                m = re.match(r"v?(\d+)", f.read(40).strip())
        except (OSError, UnicodeError):
            m = None
        if m:
            return m.group(1)
    engines = pkg.get("engines")
    text = str(engines.get("node") or "") if isinstance(engines, dict) else ""
    m = re.search(r"\d+", text)
    if not m:
        return ""
    return m.group(0) + ("+" if text.strip().startswith(">") else "")


def running(name):
    conf = {}
    try:
        with open(os.path.join(run, name + ".conf"), encoding="utf-8") as f:
            for line in f:
                k, _, v = line.rstrip("\n").partition("=")
                conf[k] = v
        out = subprocess.run(["ps", "-o", "lstart=", "-p", conf["PID"]], capture_output=True, text=True,
                             env={"LC_ALL": "C", "PATH": "/usr/bin:/bin"}, timeout=5).stdout.strip()
    except (OSError, KeyError, ValueError, subprocess.SubprocessError):
        return None
    return conf if out and out == conf.get("LSTART") else None


try:
    names = [only] if only else sorted(os.listdir(htdocs), key=str.lower)
except OSError:
    names = []
for name in names:
    d = os.path.join(htdocs, name)
    if not re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9 ._-]*", name) or os.path.islink(d):
        continue
    if any(os.path.exists(os.path.join(d, f)) for f in ("wp-config.php", "index.php", "artisan")):
        continue
    try:
        with open(os.path.join(d, "package.json"), encoding="utf-8") as f:
            pkg = json.load(f)
    except (OSError, ValueError):
        continue
    if not isinstance(pkg, dict):
        continue
    deps = {}
    for key in ("dependencies", "devDependencies"):
        if isinstance(pkg.get(key), dict):
            deps.update(pkg[key])
    scripts = pkg.get("scripts") if isinstance(pkg.get("scripts"), dict) else {}
    kind = next((label for dep, label in KINDS if dep in deps), "")
    if not kind and not ("dev" in scripts or "start" in scripts):
        continue
    conf = running(name)
    print("|".join(("P", name, kind or "Node", "marcha" if conf else "parado", conf.get("MODE", "") if conf else "",
                    "http://127.0.0.1:%s" % conf["PORT"] if conf and conf.get("PORT", "").isdigit() else "",
                    need(d, pkg), "1" if os.path.isdir(os.path.join(d, "node_modules")) else "0",
                    ("d" if "dev" in scripts else "") + ("b" if "build" in scripts else "") + ("s" if "start" in scripts else ""))))
'

function node_lines() {
    python3 -I -c "$NODE_LIST_PY" "$HTDOCS_DIR" "$NODE_RUN_DIR" "$@"
}

function gui_node() {
    node_lines | tr -d '\000-\011\013-\037'
}

# La carpeta bin de un Node que valga para lo que pide el proyecto (26, 24+ o nada: el mas nuevo de los
# que coincidan). De Nexum, de nvm o el del sistema; los nuevos, primero.
function node_find() {
    local want=$1 min=${1%+} d v major key best="" best_key=-1 sys
    for d in "$NODE_DIR"/v*/bin "$HOME"/.nvm/versions/node/v*/bin; do
        [ -x "$d/node" ] && [ -x "$d/npm" ] || continue
        v=$(basename "$(dirname "$d")")
        [[ "$v" =~ ^v([0-9]+)\.([0-9]+)\.([0-9]+)$ ]] || continue
        major=${BASH_REMATCH[1]}
        key=$(( major * 1000000 + BASH_REMATCH[2] * 1000 + BASH_REMATCH[3] ))
        if [ -n "$want" ]; then
            if [[ "$want" == *+ ]]; then [ "$major" -ge "$min" ] || continue; else [ "$major" -eq "$min" ] || continue; fi
        fi
        [ "$key" -gt "$best_key" ] && { best=$d; best_key=$key; }
    done
    if [ -z "$best" ]; then
        sys=$(command -v node 2> /dev/null)
        if [ -n "$sys" ] && [ -x "$(dirname "$sys")/npm" ]; then
            major=$("$sys" -v 2> /dev/null | sed -E 's/^v([0-9]+).*/\1/')
            if [[ "$major" =~ ^[0-9]+$ ]] && { [ -z "$want" ] \
                    || { [[ "$want" == *+ ]] && [ "$major" -ge "$min" ]; } || [ "$major" -eq "${min:-0}" ]; }; then
                best=$(dirname "$sys")
            fi
        fi
    fi
    [ -n "$best" ] && echo "$best"
}

# Descarga Node <mayor> de nodejs.org en ~/.nexum/node y lo comprueba con su lista de sumas sha256
function node_install() {
    local major=$1 base=https://nodejs.org/dist os arch sums name sha got tmp top version tls=(--proto =https --tlsv1.2)
    [[ "$major" =~ ^[0-9]+$ ]] || { echo "Versión de Node no válida: $major"; return 1; }
    case "$(uname -s)" in
        Darwin) os=darwin ;;
        Linux) os=linux ;;
        *) echo "Sistema sin Node descargable: $(uname -s)"; return 1 ;;
    esac
    case "$(uname -m)" in
        arm64|aarch64) arch=arm64 ;;
        x86_64|amd64) arch=x64 ;;
        *) echo "Procesador sin Node descargable: $(uname -m)"; return 1 ;;
    esac
    # (en las pruebas, de una carpeta local)
    [ -n "$TEST_DIR" ] && [ -n "$LVM_NODE_BASE" ] && { base=$LVM_NODE_BASE; tls=(); }
    echo "Descargando Node $major de nodejs.org ($os, $arch)..."
    mkdir -p -m 700 "$NODE_DIR" || return 1
    tmp=$(mktemp -d "$NODE_DIR/descarga.XXXXXX") || return 1
    if ! sums=$(curl -q -fsSL "${tls[@]}" --retry 2 --max-time 60 "$base/latest-v$major.x/SHASUMS256.txt"); then
        rm -rf "$tmp"
        echo "No se ha podido leer la lista de Node $major en nodejs.org"
        return 1
    fi
    name=$(awk -v rx="^node-v$major\\\\.[0-9]+\\\\.[0-9]+-$os-$arch\\\\.tar\\\\.gz$" '$2 ~ rx { print $2; exit }' <<< "$sums")
    sha=$(awk -v n="$name" '$2 == n { print $1; exit }' <<< "$sums")
    if [ -z "$name" ] || [[ ! "$sha" =~ ^[0-9a-f]{64}$ ]]; then
        rm -rf "$tmp"
        echo "Node $major no tiene paquete para $os $arch"
        return 1
    fi
    if ! curl -q -fsSL "${tls[@]}" --retry 2 --max-time 900 -o "$tmp/node.tar.gz" "$base/latest-v$major.x/$name"; then
        rm -rf "$tmp"
        echo "No se ha podido descargar $name"
        return 1
    fi
    if command -v sha256sum > /dev/null; then got=$(sha256sum "$tmp/node.tar.gz" | cut -d' ' -f1); else got=$(shasum -a 256 "$tmp/node.tar.gz" | cut -d' ' -f1); fi
    if [ "$got" != "$sha" ]; then
        rm -rf "$tmp"
        echo "La descarga de Node no coincide con su suma sha256 (${got:-ninguna}): no se instala."
        return 1
    fi
    top=${name%.tar.gz}
    version=${top#node-}
    version=${version%%-*}
    if ! tar -xzf "$tmp/node.tar.gz" -C "$tmp" "$top" 2> /dev/null || [ ! -x "$tmp/$top/bin/node" ]; then
        rm -rf "$tmp"
        echo "El paquete de Node no trae su programa: no se instala."
        return 1
    fi
    rm -rf "${NODE_DIR:?}/$version"
    mv "$tmp/$top" "$NODE_DIR/$version" || { rm -rf "$tmp"; return 1; }
    rm -rf "$tmp"
    echo "Node $version instalado en $NODE_DIR"
}

# El pid del servidor de un proyecto, si sigue siendo aquel (misma hora de arranque)
function node_pid() {
    local conf=$NODE_RUN_DIR/$1.conf pid start
    [ -f "$conf" ] || return 1
    pid=$(sed -n 's/^PID=//p' "$conf")
    start=$(sed -n 's/^LSTART=//p' "$conf")
    [[ "$pid" =~ ^[0-9]+$ ]] && [ -n "$start" ] || return 1
    [ "$(LC_ALL=C ps -o lstart= -p "$pid" 2> /dev/null | sed -E 's/^ +//; s/ +$//')" == "$start" ] || return 1
    echo "$pid"
}

function node_free_port() {
    python3 -I -c '
import socket, sys
for port in range(int(sys.argv[1]), int(sys.argv[2]) + 1):
    s = socket.socket()
    try:
        s.bind(("127.0.0.1", port))
    except OSError:
        continue
    finally:
        s.close()
    print(port)
    break
' "$NODE_PORT_FROM" "$NODE_PORT_TO"
}

# Instala lo que le falte: lo pide su fichero de bloqueo. Los scripts de sus paquetes se ejecutan con tu usuario
function node_deps() {
    local dir=$1 bin=$2 lock=""
    shift 2
    for lock in package-lock.json pnpm-lock.yaml yarn.lock; do
        [ -f "$dir/$lock" ] && break
        lock=""
    done
    if [ -d "$dir/node_modules" ] && { [ -z "$lock" ] || [ ! "$dir/$lock" -nt "$dir/node_modules" ]; }; then
        echo "Dependencias: ya están instaladas"
        return 0
    fi
    echo "Instalando las dependencias..."
    case "$lock" in
        package-lock.json) ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npm" ci --no-audit --no-fund ) ;;
        pnpm-lock.yaml) ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npx" --yes pnpm install --frozen-lockfile ) ;;
        yarn.lock) ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npx" --yes yarn install --frozen-lockfile ) ;;
        *) ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npm" install --no-audit --no-fund ) ;;
    esac || { echo "No se han podido instalar las dependencias"; return 1; }
    touch "$dir/node_modules"
}

# Astro con un adaptador de un alojamiento (Vercel, Netlify, Cloudflare) no se puede servir en este equipo:
# se compila con el de Node, sin tocar su configuracion ni su package.json (todo dentro de node_modules)
function node_build_astro() {
    local dir=$1 bin=$2 conf="" c
    shift 2
    for c in astro.config.mjs astro.config.ts astro.config.mts astro.config.js astro.config.cjs; do
        [ -f "$dir/$c" ] && { conf=$c; break; }
    done
    if [ -z "$conf" ] || ! grep -qE "@astrojs/(vercel|netlify|cloudflare)" "$dir/$conf"; then
        ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npx" --no-install astro build )
        return
    fi
    if [ ! -f "$dir/node_modules/@astrojs/node/package.json" ]; then
        if [ -f "$dir/pnpm-lock.yaml" ] || [ -f "$dir/yarn.lock" ]; then
            echo "Este proyecto usa un adaptador de alojamiento: añade @astrojs/node a sus dependencias para compilarlo aquí."
            return 1
        fi
        ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npm" install --no-save --no-audit --no-fund @astrojs/node ) || return 1
    fi
    printf "import base from '../%s';\nimport node from '@astrojs/node';\nexport default { ...base, adapter: node({ mode: 'standalone' }) };\n" "$conf" \
        > "$dir/node_modules/.nexum-astro.config.mjs" || return 1
    echo "(compilando con @astrojs/node en lugar de su adaptador de alojamiento; el proyecto no cambia)"
    ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npx" --no-install astro build --config node_modules/.nexum-astro.config.mjs )
}

# Lo que deja el servidor en marcha, en NODE_CMD: node_command <carpeta> <tipo> <modo> <scripts> <bin> <puerto>
NODE_CMD=()
function node_command() {
    local dir=$1 kind=$2 mode=$3 scripts=$4 bin=$5 port=$6 root
    NODE_CMD=()
    if [ "$mode" == desarrollo ]; then
        case "$kind" in
            Astro) NODE_CMD=("$bin/npx" --no-install astro dev --host 127.0.0.1 --port "$port") ;;
            Next) NODE_CMD=("$bin/npx" --no-install next dev -H 127.0.0.1 -p "$port") ;;
            Nuxt) NODE_CMD=("$bin/npx" --no-install nuxt dev --host 127.0.0.1 --port "$port") ;;
            SvelteKit|Vite) NODE_CMD=("$bin/npx" --no-install vite --host 127.0.0.1 --port "$port" --strictPort) ;;
            *) if [[ "$scripts" == *d* ]]; then NODE_CMD=("$bin/npm" run dev); elif [[ "$scripts" == *s* ]]; then NODE_CMD=("$bin/npm" start); fi ;;
        esac
    else
        case "$kind" in
            Astro)
                if [ -f "$dir/dist/server/entry.mjs" ]; then
                    NODE_CMD=("$bin/node" dist/server/entry.mjs)
                else
                    root=dist
                    [ -d "$dir/dist/client" ] && root=dist/client
                    NODE_CMD=(python3 -I -m http.server --bind 127.0.0.1 --directory "$root" "$port")
                fi
                ;;
            Next) NODE_CMD=("$bin/npx" --no-install next start -H 127.0.0.1 -p "$port") ;;
            Nuxt) NODE_CMD=("$bin/node" .output/server/index.mjs) ;;
            SvelteKit|Vite) NODE_CMD=("$bin/npx" --no-install vite preview --host 127.0.0.1 --port "$port" --strictPort) ;;
            *) [[ "$scripts" == *s* ]] && NODE_CMD=("$bin/npm" start) ;;
        esac
    fi
    [ "${#NODE_CMD[@]}" -gt 0 ]
}

# node-arrancar <carpeta> [desarrollo|compilado]
function node_start() {
    local folder=${1%/} mode=${2:-desarrollo} dir line kind state need deps scripts bin port log conf pid n x steps=() e=()
    if [ "${EUID:-$(id -u)}" -eq 0 ]; then
        echo "Los proyectos de Node no se arrancan como root."
        return 1
    fi
    [[ "$mode" =~ ^(desarrollo|compilado)$ ]] || { echo "El modo es desarrollo o compilado"; return 1; }
    valid_project "$folder" || return 1
    dir=$HTDOCS_DIR/$folder
    line=$(node_lines "$folder")
    if [ -z "$line" ]; then
        echo "$folder no es un proyecto de Node"
        return 1
    fi
    IFS='|' read -r x x kind state x x need deps scripts <<< "$line"
    if [ "$mode" == compilado ] && [ "$kind" == Node ] && [[ "$scripts" != *s* ]]; then
        echo "$folder no tiene un script start: no se sabe cómo servirlo compilado"
        return 1
    fi
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] $folder ($kind, $mode): Node ${need:-el que haya}, dependencias y servidor en 127.0.0.1"
        return 0
    fi
    steps=("Preparar Node ${need:-}" "Instalar las dependencias")
    [ "$mode" == compilado ] && steps+=("Compilar el proyecto")
    steps+=("Arrancar el servidor")
    task_plan "Arrancando $folder" "${steps[@]}"
    [ "$state" == marcha ] && node_stop "$folder" > /dev/null

    task_step
    bin=$(node_find "$need")
    if [ -z "$bin" ]; then
        x=${need%+}
        node_install "${x:-$NODE_DEFAULT_MAJOR}" || return 1
        bin=$(node_find "$need")
        [ -n "$bin" ] || { echo "No se encuentra el Node recién instalado"; return 1; }
    fi
    echo "Node $("$bin/node" -v) ($bin)"
    port=$(node_free_port)
    [ -n "$port" ] || { echo "No hay ningún puerto libre entre $NODE_PORT_FROM y $NODE_PORT_TO"; return 1; }
    e=("HOME=$HOME" "USER=${USER:-$(id -un)}" "LANG=${LANG:-es_ES.UTF-8}" "TERM=dumb" "CI=1"
       "PATH=$bin:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin" "HOST=127.0.0.1" "PORT=$port" "NO_COLOR=1"
       "ASTRO_TELEMETRY_DISABLED=1" "NEXT_TELEMETRY_DISABLED=1")

    task_step
    node_deps "$dir" "$bin" "${e[@]}" || return 1

    if [ "$mode" == compilado ]; then
        task_step
        echo "Compilando..."
        if [ "$kind" == Astro ]; then
            node_build_astro "$dir" "$bin" "${e[@]}"
        elif [[ "$scripts" == *b* ]]; then
            ( cd "$dir" && /usr/bin/env -i "${e[@]}" "$bin/npm" run build )
        fi || { echo "No se ha podido compilar $folder"; return 1; }
    fi

    task_step
    node_command "$dir" "$kind" "$mode" "$scripts" "$bin" "$port" || { echo "$folder no tiene un script dev ni start"; return 1; }
    mkdir -p -m 700 "$NODE_RUN_DIR" || return 1
    log=$NODE_RUN_DIR/$folder.log conf=$NODE_RUN_DIR/$folder.conf
    : > "$log" && chmod 600 "$log" || return 1
    # (en su propia sesion, para pararlo con todos sus hijos y que siga al cerrar la ventana)
    ( cd "$dir" && exec python3 -I -c 'import os, sys
os.setsid()
os.execv("/usr/bin/env", ["env", "-i"] + sys.argv[1:])' "${e[@]}" "${NODE_CMD[@]}" >> "$log" 2>&1 < /dev/null ) &
    pid=$!
    ( umask 077; printf 'PID=%s\nLSTART=%s\nPORT=%s\nMODE=%s\n' "$pid" \
        "$(LC_ALL=C ps -o lstart= -p "$pid" 2> /dev/null | sed -E 's/^ +//; s/ +$//')" "$port" "$mode" > "$conf" ) || return 1
    echo "Arrancando el servidor en http://127.0.0.1:$port ..."
    for n in $(seq 360); do
        if ! kill -0 "$pid" 2> /dev/null; then
            rm -f "$conf"
            echo "El servidor de $folder se ha parado al arrancar. Lo último que ha dicho:"
            tail -20 "$log" | sed 's/^/  /'
            return 1
        fi
        curl -q -s -o /dev/null --noproxy '*' --max-time 2 "http://127.0.0.1:$port/" && break
        sleep 0.5
    done
    if [ "$n" -ge 360 ]; then
        node_stop "$folder" > /dev/null
        echo "El servidor de $folder no responde en http://127.0.0.1:$port tras 3 minutos: se para. Lo último que ha dicho:"
        tail -20 "$log" | sed 's/^/  /'
        return 1
    fi
    echo "$folder en marcha ($mode): http://127.0.0.1:$port"
    echo "URL|http://127.0.0.1:$port"
}

# node-parar <carpeta>: el servidor con todos sus hijos y, si se esta compartiendo, tambien su tunel (ese
# puerto podria acabar siendo de otro proyecto)
function node_stop() {
    local folder=${1%/} pid conf=$NODE_RUN_DIR/${1%/}.conf port n
    [[ "$folder" =~ ^[A-Za-z0-9_][A-Za-z0-9\ ._-]*$ ]] || { echo "Carpeta no válida: $folder"; return 1; }
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] se para $folder"
        return 0
    fi
    pid=$(node_pid "$folder")
    if [ -z "$pid" ]; then
        rm -f "$conf"
        echo "$folder no está en marcha"
        return 0
    fi
    port=$(sed -n 's/^PORT=//p' "$conf")
    if [[ "$port" =~ ^[0-9]+$ ]] && [ -f "$TUNNEL_STATE" ] && grep -qF "\"target\": \"http://127.0.0.1:$port\"" "$TUNNEL_STATE"; then
        tunnel_close > /dev/null
        echo "Túnel cerrado: compartía este proyecto"
    fi
    kill -TERM -- "-$pid" 2> /dev/null
    for n in $(seq 20); do
        kill -0 -- "-$pid" 2> /dev/null || break
        sleep 0.25
    done
    kill -KILL -- "-$pid" 2> /dev/null
    rm -f "$conf"
    echo "$folder parado"
}

# node-registro <carpeta>: lo ultimo que ha dicho su servidor
function node_log() {
    local folder=${1%/} log=$NODE_RUN_DIR/${1%/}.log
    [[ "$folder" =~ ^[A-Za-z0-9_][A-Za-z0-9\ ._-]*$ ]] || { echo "Carpeta no válida: $folder"; return 1; }
    if [ -f "$log" ]; then
        tail -300 "$log"
    else
        echo "$folder aún no ha arrancado desde aquí"
    fi
}

# Nginx (pestaña Nginx): lo del Mac. El PHP-FPM de la versión activa (/Applications/XAMPP), lo que hace
# falta para compilarlo (las herramientas de Xcode y pcre2 y openssl@3 de Homebrew, con tu usuario) y la
# confianza del navegador
NGINX_PHP_SOCK=$LINK/xamppfiles/var/run/php-fpm.sock

function nginx_deps_missing() {
    return 1
}

function nginx_build_deps() {
    local f missing=()
    echo "Lo que hace falta para compilar Nginx (las herramientas de Xcode; pcre2 y openssl@3 de Homebrew)"
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] brew install de los que falten"; return 0; }
    if ! xcode-select -p > /dev/null 2>&1; then
        echo "  Faltan las herramientas de línea de órdenes de Xcode: xcode-select --install, y vuelve a probar"
        return 1
    fi
    command -v brew > /dev/null || { echo "  Falta Homebrew (brew.sh): instálalo y vuelve a probar"; return 1; }
    for f in pcre2 openssl@3; do
        brew_quiet list --versions "$f" > /dev/null 2>&1 || missing+=("$f")
    done
    [ ${#missing[@]} -eq 0 ] && { echo "  Ya estan todas instaladas"; return 0; }
    echo "  Se instalan con Homebrew: ${missing[*]}"
    { brew_quiet install --quiet "${missing[@]}" 2>&1 > /dev/null; } | brew_filter >&2
    [ "${PIPESTATUS[0]}" -eq 0 ] || { echo "  No se han podido instalar con Homebrew: ${missing[*]}"; return 1; }
}

# (con pcre2 y openssl@3 de Homebrew)
function nginx_build_flags() {
    local pcre ssl
    pcre=$(brew_quiet --prefix pcre2 2> /dev/null) && ssl=$(brew_quiet --prefix openssl@3 2> /dev/null) \
        || { echo "No están pcre2 y openssl@3 de Homebrew"; return 1; }
    NGINX_BUILD_FLAGS=(--with-cc-opt="-I$pcre/include -I$ssl/include" --with-ld-opt="-L$pcre/lib -L$ssl/lib")
}

# Safari y Chrome aceptan sin aviso el certificado de <nombre>.localhost: va a tus ajustes de confianza
# del llavero, solo para servidores (ssl), como el de *.docker.local
function nginx_trust() {
    local host=$1 crt=$NGINX_DIR/certs/$1.crt
    # (en las pruebas, nunca en el llavero de verdad)
    [ -n "$TEST_DIR" ] && return 0
    [ -f "$crt" ] || [ "$DRY" -eq 1 ] || return 0
    if [ "$DRY" -eq 0 ] && security verify-cert -c "$crt" -p ssl -s "$host" > /dev/null 2>&1; then
        return 0
    fi
    echo "El Mac te pide la contraseña para que el navegador acepte el certificado de $host..."
    if ! run security add-trusted-cert -r trustRoot -p ssl -k "$HOME/Library/Keychains/login.keychain-db" "$crt"; then
        echo "No se ha cambiado (¿has cancelado la contraseña?): pulsa «Confiar» en la pestaña Nginx"
        return 0
    fi
    echo "El navegador acepta el certificado de $host (Safari, Chrome; Firefox, si usa los certificados del Mac)"
}
# Nginx (pestaña Nginx, 1.57.38): un servidor web aparte de las versiones de PHP, para los proyectos de
# htdocs que se le añadan. Uno para todo el equipo, en ~/.nexum/nginx y con tu usuario (nunca root ni
# sudo, salvo para instalar en Linux lo que hace falta para compilarlo), solo en este equipo (127.0.0.1
# y ::1) y en sus puertos (8080 y 8443 de serie, en Configuración, Nginx). Cada proyecto, por su nombre:
# http://<carpeta>.localhost:8080 y https://<carpeta>.localhost:8443 (el navegador lleva cualquier
# .localhost a este equipo sin tocar /etc/hosts), con el PHP-FPM de la versión de PHP activa y sus BBDD.
# Se compila de su código, fijado por su huella (la del .tar.gz de nginx.org, firmado por quien publica
# Nginx: se comprobó al fijarla). Para otra versión: su .tar.gz.asc de nginx.org/en/download.html
NGINX_VERSION=1.30.7
NGINX_SHA256=2565b5c837050e958f70fb0f73c48e2bca4542ad349fd356f46fb0c72610bc6e
NGINX_DIR=$LOG_DIR/nginx
NGINX_PREFIX=$NGINX_DIR/programa
NGINX_BIN=$NGINX_PREFIX/sbin/nginx
NGINX_SETTINGS=$NGINX_DIR/ajustes
NGINX_LIST=$NGINX_DIR/proyectos
NGINX_CONF=$NGINX_DIR/conf/nginx.conf
NGINX_RUN=$NGINX_DIR/run
NGINX_ERROR_LOG=$NGINX_DIR/logs/error.log
NGINX_HTTP_DEFAULT=8080
NGINX_HTTPS_DEFAULT=8443

# nginx_get HTTP|HTTPS: el puerto de Configuración, o el de serie si no hay o no vale
function nginx_get() {
    local v="" def=$NGINX_HTTP_DEFAULT
    [ "$1" == HTTPS ] && def=$NGINX_HTTPS_DEFAULT
    [ -f "$NGINX_SETTINGS" ] && v=$(sed -n "s/^$1=//p" "$NGINX_SETTINGS" | tail -1)
    if [[ "$v" =~ ^[1-9][0-9]{3,4}$ ]] && [ "$v" -le 65535 ]; then
        echo "$v"
    else
        echo "$def"
    fi
}

# ¿Se usa Nginx? Apagado de serie: se enciende en Configuración, Nginx (nginx-usar si), y entonces sale su
# pestaña. Apagarlo lo para y oculta la pestaña, sin borrar nada
function nginx_used() {
    [ -f "$NGINX_DIR/usar" ]
}

# nginx-usar si|no
function nginx_use() {
    case $1 in
        si|no) ;;
        *) echo "Uso: nexum nginx-usar si|no"; return 1 ;;
    esac
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] Nginx: $1"; return 0; }
    if [ "$1" == si ]; then
        mkdir -p -m 700 "$NGINX_DIR" && : > "$NGINX_DIR/usar" || return 1
        echo "Nginx encendido: su pestaña ya sale en el menú lateral$(nginx_installed || echo " (instálalo desde ella)")"
    else
        nginx_running && nginx_stop
        rm -f "$NGINX_DIR/usar" || return 1
        echo "Nginx apagado: su pestaña ya no sale (sus proyectos y ajustes se quedan para cuando lo vuelvas a encender)"
    fi
}

function nginx_installed() {
    [ -x "$NGINX_BIN" ] && [ ! -L "$NGINX_BIN" ]
}

function nginx_installed_version() {
    cat "$NGINX_PREFIX/version" 2> /dev/null
}

# El nombre de un proyecto en Nginx: <carpeta>.localhost, en minúsculas y con guiones en lugar de lo que
# no va en un nombre (Mi Tienda_2 -> mi-tienda-2.localhost). Nada si no queda ninguna letra o número
function nginx_host() {
    local h
    h=$(printf '%s' "$1" | tr 'A-Z' 'a-z' | sed 's/[^a-z0-9-]\{1,\}/-/g; s/^-*//; s/-*$//' | cut -c1-63 | sed 's/-*$//')
    [ -n "$h" ] && echo "$h.localhost"
}

# Los proyectos añadidos: carpeta|raíz, uno por línea (raíz: la subcarpeta que se sirve, como public, o
# vacía para la carpeta entera). Solo los que siguen siendo una carpeta de proyecto válida
function nginx_projects() {
    local folder root
    [ -f "$NGINX_LIST" ] || return 0
    while IFS='|' read -r folder root; do
        [[ "$folder" =~ ^[A-Za-z0-9_][A-Za-z0-9\ ._-]*$ ]] || continue
        [[ "$root" =~ ^([A-Za-z0-9_][A-Za-z0-9._-]*(/[A-Za-z0-9_][A-Za-z0-9._-]*)*)?$ ]] || continue
        [[ "/$root/" == */../* ]] && continue
        echo "$folder|$root"
    done < "$NGINX_LIST"
}

# La raíz que se sirve de un proyecto, si no se dice: public (Laravel, Symfony), web (Symfony antiguo) o
# la carpeta entera
function nginx_root_guess() {
    local d=$HTDOCS_DIR/$1
    if [ -f "$d/public/index.php" ] || [ -f "$d/public/index.html" ]; then
        echo public
    elif [ -f "$d/web/app.php" ] || [ -f "$d/web/index.php" ]; then
        echo web
    fi
}

function nginx_running() {
    local pid
    pid=$(cat "$NGINX_RUN/nginx.pid" 2> /dev/null)
    [[ "$pid" =~ ^[0-9]+$ ]] && kill -0 "$pid" 2> /dev/null && ps -p "$pid" -o comm= 2> /dev/null | grep -q nginx
}

# Cómo está el PHP de la versión activa para Nginx: ok (su PHP-FPM responde), parado (no está en marcha)
# o sin-fpm (la versión activa no tiene PHP-FPM, como un XAMPP oficial)
function nginx_php_state() {
    if [ -S "$NGINX_PHP_SOCK" ]; then
        echo ok
    elif [ -n "$(active_dir)" ] && ! is_fpm_install "$(active_dir)"; then
        echo sin-fpm
    else
        echo parado
    fi
}

# ¿Está libre <puerto> en este equipo? (lo que ya escucha ahí no deja arrancar a Nginx)
function nginx_port_free() {
    python3 -I -c '
import socket, sys
s = socket.socket()
s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
try:
    s.bind(("127.0.0.1", int(sys.argv[1])))
except OSError:
    sys.exit(1)' "$1"
}

# Descarga (comprobada por su huella) y compila Nginx en ~/.nexum/nginx/programa, con tu usuario. Si ya
# estaba en marcha, sigue con el nuevo. Sin su lista de pasos (nginx_install o Componentes la ponen)
function nginx_build() {
    local tmp url=https://nginx.org/download/nginx-$NGINX_VERSION.tar.gz sha=$NGINX_SHA256 got jobs was=0 tls=(--proto =https --tlsv1.2)
    [ "$EUID" -eq 0 ] && { echo "Nginx se instala con tu usuario, no como root"; return 1; }
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] descarga de Nginx $NGINX_VERSION (comprobada por su huella) y compilación en $NGINX_PREFIX"
        return 0
    fi
    # (en las pruebas, de una carpeta local)
    [ -n "$TEST_DIR" ] && [ -n "$LVM_NGINX_URL" ] && { url=$LVM_NGINX_URL sha=$LVM_NGINX_SHA tls=(); }
    for got in "$NGINX_DIR" "$NGINX_PREFIX"; do
        [ -L "$got" ] && { echo "$got es un enlace: no se toca"; return 1; }
    done
    mkdir -p -m 700 "$NGINX_DIR" || return 1
    tmp=$(mktemp -d "$NGINX_DIR/compilar.XXXXXX") || return 1
    echo "Descargando Nginx $NGINX_VERSION de nginx.org..."
    if ! curl -q -fsSL "${tls[@]}" --retry 2 --max-time 300 -o "$tmp/nginx.tar.gz" "$url"; then
        rm -rf "$tmp"
        echo "No se ha podido descargar Nginx $NGINX_VERSION"
        return 1
    fi
    if command -v sha256sum > /dev/null; then
        got=$(sha256sum "$tmp/nginx.tar.gz" | cut -d' ' -f1)
    else
        got=$(shasum -a 256 "$tmp/nginx.tar.gz" | cut -d' ' -f1)
    fi
    if [ "$got" != "$sha" ]; then
        rm -rf "$tmp"
        echo "La descarga de Nginx no es la que se espera (su huella no coincide): no se instala"
        return 1
    fi
    echo "  Huella de Nginx $NGINX_VERSION: buena"
    tar -xzf "$tmp/nginx.tar.gz" -C "$tmp" || { rm -rf "$tmp"; echo "No se ha podido abrir el código de Nginx"; return 1; }
    jobs=$(getconf _NPROCESSORS_ONLN 2> /dev/null || echo 2)
    echo "Compilando Nginx $NGINX_VERSION (menos de un minuto)..."
    # (lo que se usa con PHP: https, http/2, gzip; sin los módulos de correo ni otros protocolos de aplicaciones)
    NGINX_BUILD_FLAGS=()
    nginx_build_flags || { rm -rf "$tmp"; return 1; }
    if ! ( cd "$tmp/nginx-$NGINX_VERSION" \
            && ./configure --prefix="$NGINX_PREFIX" --with-http_ssl_module --with-http_v2_module \
                --with-http_realip_module --with-http_gzip_static_module --with-pcre-jit \
                --without-http_uwsgi_module --without-http_scgi_module --without-mail_pop3_module \
                "${NGINX_BUILD_FLAGS[@]}" > "$tmp/configure.log" 2>&1 \
            && make -j"$jobs" > "$tmp/make.log" 2>&1 \
            && make install DESTDIR="$tmp/stage" > "$tmp/install.log" 2>&1 ); then
        echo "No se ha podido compilar Nginx. Lo último que ha dicho:"
        tail -15 "$(ls -t "$tmp"/*.log | head -1)" | sed 's/^/  /'
        rm -rf "$tmp"
        return 1
    fi
    echo "$NGINX_VERSION" > "$tmp/stage$NGINX_PREFIX/version"
    nginx_running && was=1
    rm -rf "$NGINX_PREFIX.anterior"
    [ -d "$NGINX_PREFIX" ] && mv "$NGINX_PREFIX" "$NGINX_PREFIX.anterior"
    if ! mv "$tmp/stage$NGINX_PREFIX" "$NGINX_PREFIX"; then
        [ -d "$NGINX_PREFIX.anterior" ] && mv "$NGINX_PREFIX.anterior" "$NGINX_PREFIX"
        rm -rf "$tmp"
        echo "No se ha podido poner Nginx en $NGINX_PREFIX"
        return 1
    fi
    rm -rf "$tmp" "$NGINX_PREFIX.anterior"
    echo "Nginx $NGINX_VERSION instalado en $NGINX_PREFIX"
    # (el que estaba en marcha, con el programa nuevo)
    if [ $was -eq 1 ]; then
        nginx_stop > /dev/null
        nginx_start
    fi
}

# nginx-instalar: lo que hace falta para compilarlo y Nginx
function nginx_install() {
    nginx_used || { echo "Nginx está apagado: enciéndelo en Configuración, Nginx (nginx-usar si)"; return 1; }
    task_plan "Instalando Nginx $NGINX_VERSION" "Lo que hace falta para compilarlo" "Nginx $NGINX_VERSION"
    task_step
    nginx_build_deps || return 1
    task_step
    nginx_build
}

# Certificado propio de <nombre>.localhost (no es de una CA: solo vale para ese nombre), en una carpeta
# solo tuya. Se rehace si falta o no es de ese nombre
function nginx_cert() {
    local host=$1 c=$NGINX_DIR/certs
    if [ -s "$c/$host.crt" ] && [ -s "$c/$host.key" ] \
            && openssl x509 -in "$c/$host.crt" -noout -text 2> /dev/null | grep -qF "DNS:$host"; then
        return 0
    fi
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] certificado propio de $host en $c"; return 0; }
    mkdir -p -m 700 "$NGINX_DIR" "$c" || return 1
    # (las extensiones en un fichero propio y no con -addext: ver make_selfsigned)
    if ! ( umask 077
            printf '[req]\ndistinguished_name = dn\nx509_extensions = ext\nprompt = no\n[dn]\nCN = %s\n[ext]\nbasicConstraints = critical,CA:FALSE\nextendedKeyUsage = serverAuth\nsubjectAltName = DNS:%s\n' "$host" "$host" > "$c/$host.cnf" \
            && openssl req -x509 -nodes -newkey rsa:2048 -days 3650 -config "$c/$host.cnf" \
            -keyout "$c/$host.key" -out "$c/$host.crt" > /dev/null 2>&1 ); then
        rm -f "$c/$host.key" "$c/$host.crt" "$c/$host.cnf"
        echo "No se ha podido crear el certificado de $host"
        return 1
    fi
    rm -f "$c/$host.cnf"
}

# La configuración entera de Nginx (conf/nginx.conf), de los ajustes y los proyectos. Se prueba antes de
# cambiarla: si Nginx no la acepta, se queda la de antes
function nginx_write_conf() {
    local http https folder root host dir ip new
    http=$(nginx_get HTTP) https=$(nginx_get HTTPS)
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] configuración de Nginx en $NGINX_CONF"; return 0; }
    mkdir -p -m 700 "$NGINX_DIR" "$NGINX_DIR/conf" "$NGINX_RUN" "$NGINX_RUN/tmp" "$NGINX_DIR/logs" || return 1
    new=$NGINX_CONF.nuevo
    {
        cat << EOF
# Configuración de Nginx de Nexum Dev Stack: la escribe el gestor (pestaña Nginx), no se edita a mano
worker_processes 1;
pid "$NGINX_RUN/nginx.pid";
error_log "$NGINX_ERROR_LOG" warn;
events { worker_connections 256; }
http {
    include "$NGINX_PREFIX/conf/mime.types";
    default_type application/octet-stream;
    access_log off;
    sendfile on;
    server_tokens off;
    client_max_body_size 256m;
    client_body_temp_path "$NGINX_RUN/tmp/body";
    proxy_temp_path "$NGINX_RUN/tmp/proxy";
    fastcgi_temp_path "$NGINX_RUN/tmp/fastcgi";
    # Lo que no es el nombre de un proyecto (otro nombre, la IP o un dominio real), sin respuesta
    server {
        listen 127.0.0.1:$http default_server;
        listen [::1]:$http default_server;
        listen 127.0.0.1:$https ssl default_server;
        listen [::1]:$https ssl default_server;
        ssl_reject_handshake on;
        return 444;
    }
EOF
        while IFS='|' read -r folder root; do
            host=$(nginx_host "$folder") || continue
            [ -d "$HTDOCS_DIR/$folder" ] || continue
            dir=$HTDOCS_DIR/$folder${root:+/$root}
            cat << EOF
    # $folder
    server {
EOF
            for ip in 127.0.0.1 "[::1]"; do
                printf '        listen %s:%s;\n        listen %s:%s ssl;\n' "$ip" "$http" "$ip" "$https"
            done
            cat << EOF
        http2 on;
        server_name $host;
        ssl_certificate "$NGINX_DIR/certs/$host.crt";
        ssl_certificate_key "$NGINX_DIR/certs/$host.key";
        root "$dir";
        index index.php index.html;
        # Ficheros ocultos (.env, .git...) y dependencias, nunca
        location ~ /\.(?!well-known/) { deny all; }
        location ~ ^/(vendor|node_modules)/ { deny all; }
        location / { try_files \$uri \$uri/ /index.php?\$query_string; }
        location ~ [^/]\.php(/|\$) {
            fastcgi_split_path_info ^(.+?\.php)(/.*)\$;
            try_files \$fastcgi_script_name =404;
            include "$NGINX_PREFIX/conf/fastcgi_params";
            fastcgi_param SCRIPT_FILENAME \$document_root\$fastcgi_script_name;
            fastcgi_param PATH_INFO \$fastcgi_path_info;
            fastcgi_param HTTPS \$https if_not_empty;
            fastcgi_read_timeout 300;
            fastcgi_pass unix:$NGINX_PHP_SOCK;
        }
    }
EOF
        done < <(nginx_projects)
        echo "}"
    } > "$new" || return 1
    chmod 600 "$new"
    if nginx_installed && ! "$NGINX_BIN" -t -q -p "$NGINX_RUN" -c "$new" -e "$NGINX_ERROR_LOG" 2> "$NGINX_RUN/prueba.log"; then
        echo "Nginx no acepta la configuración nueva: se queda la de antes. Lo que dice:"
        sed 's/^/  /' "$NGINX_RUN/prueba.log" | tail -5
        rm -f "$new"
        return 1
    fi
    mv -f "$new" "$NGINX_CONF"
}

# La configuración de ahora, y si está en marcha, que la use (sin cortar lo que esté sirviendo)
function nginx_apply() {
    nginx_write_conf || return 1
    if [ "$DRY" -eq 0 ] && nginx_running; then
        "$NGINX_BIN" -p "$NGINX_RUN" -c "$NGINX_CONF" -e "$NGINX_ERROR_LOG" -s reload || return 1
    fi
    return 0
}

function nginx_start() {
    local http https p i
    [ "$EUID" -eq 0 ] && { echo "Nginx corre con tu usuario, no como root"; return 1; }
    nginx_used || { echo "Nginx está apagado: enciéndelo en Configuración, Nginx (nginx-usar si)"; return 1; }
    nginx_installed || { echo "Nginx no está instalado: instálalo en la pestaña Nginx (nginx-instalar)"; return 1; }
    if nginx_running; then
        nginx_apply || return 1
        echo "Nginx ya estaba en marcha: con la configuración de ahora"
        return 0
    fi
    http=$(nginx_get HTTP) https=$(nginx_get HTTPS)
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] Nginx en marcha en 127.0.0.1:$http y :$https"
        return 0
    fi
    for p in "$http" "$https"; do
        nginx_port_free "$p" || { echo "El puerto $p ya lo usa otro programa: cámbialo en Configuración, Nginx"; return 1; }
    done
    nginx_write_conf || return 1
    if ! "$NGINX_BIN" -p "$NGINX_RUN" -c "$NGINX_CONF" -e "$NGINX_ERROR_LOG"; then
        echo "Nginx no ha arrancado. Lo último de su registro:"
        tail -5 "$NGINX_ERROR_LOG" 2> /dev/null | sed 's/^/  /'
        return 1
    fi
    for i in $(seq 30); do
        nginx_running && break
        sleep 0.1
    done
    nginx_running || { echo "Nginx no ha arrancado (mira su registro)"; return 1; }
    echo "Nginx en marcha en este equipo: puertos $http (http) y $https (https)"
    [ "$(nginx_php_state)" == ok ] || echo "Aviso: el PHP de la versión activa no está en marcha: arráncala para que sirva PHP"
}

function nginx_stop() {
    local i
    if ! nginx_running; then
        echo "Nginx no estaba en marcha"
        return 0
    fi
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] se para Nginx"; return 0; }
    "$NGINX_BIN" -p "$NGINX_RUN" -c "$NGINX_CONF" -e "$NGINX_ERROR_LOG" -s quit 2> /dev/null
    for i in $(seq 50); do
        nginx_running || break
        sleep 0.1
    done
    nginx_running && kill -TERM "$(cat "$NGINX_RUN/nginx.pid")" 2> /dev/null
    echo "Nginx parado"
}

# nginx-anadir <carpeta> [raíz]: el proyecto, servido por <carpeta>.localhost (raíz: la subcarpeta que se
# sirve; sin ella, la que parezca: public, web o la carpeta entera)
function nginx_add() {
    local folder=${1%/} root=${2-__adivinar__} host f r
    valid_project "$folder" || return 1
    [ "$root" == __adivinar__ ] && root=$(nginx_root_guess "$folder")
    root=${root%/}
    [ "$root" == . ] && root=""
    if [ -n "$root" ] && { ! [[ "$root" =~ ^[A-Za-z0-9_][A-Za-z0-9._-]*(/[A-Za-z0-9_][A-Za-z0-9._-]*)*$ ]] || [[ "/$root/" == */../* ]]; }; then
        echo "Subcarpeta no válida: $root"
        return 1
    fi
    [ -z "$root" ] || [ -d "$HTDOCS_DIR/$folder/$root" ] || { echo "No existe $HTDOCS_DIR/$folder/$root"; return 1; }
    host=$(nginx_host "$folder") || { echo "Con el nombre de $folder no se puede hacer un nombre para Nginx"; return 1; }
    while IFS='|' read -r f r; do
        [ "$f" == "$folder" ] && continue
        [ "$(nginx_host "$f")" == "$host" ] && { echo "$f ya usa $host: cambia el nombre de una de las dos carpetas"; return 1; }
    done < <(nginx_projects)
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] $folder en Nginx: http://$host:$(nginx_get HTTP) (${root:-la carpeta entera})"
        return 0
    fi
    mkdir -p -m 700 "$NGINX_DIR" || return 1
    { nginx_projects | grep -v "^$(printf '%s' "$folder" | sed 's/[.[\*^$]/\\&/g')|"; echo "$folder|$root"; } > "$NGINX_LIST.nuevo" \
        && chmod 600 "$NGINX_LIST.nuevo" && mv -f "$NGINX_LIST.nuevo" "$NGINX_LIST" || return 1
    nginx_cert "$host" || return 1
    nginx_trust "$host"
    nginx_apply || return 1
    echo "$folder en Nginx: http://$host:$(nginx_get HTTP) y https://$host:$(nginx_get HTTPS)${root:+ (sirve $root/)}"
}

# nginx-quitar <carpeta>: deja de servirlo (su carpeta no se toca)
function nginx_remove() {
    local folder=${1%/} host
    [[ "$folder" =~ ^[A-Za-z0-9_][A-Za-z0-9\ ._-]*$ ]] || { echo "Carpeta no válida: $folder"; return 1; }
    nginx_projects | grep -q "^$(printf '%s' "$folder" | sed 's/[.[\*^$]/\\&/g')|" || { echo "$folder no está en Nginx"; return 0; }
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] $folder deja de estar en Nginx"; return 0; }
    host=$(nginx_host "$folder")
    nginx_projects | grep -v "^$(printf '%s' "$folder" | sed 's/[.[\*^$]/\\&/g')|" > "$NGINX_LIST.nuevo"
    chmod 600 "$NGINX_LIST.nuevo" && mv -f "$NGINX_LIST.nuevo" "$NGINX_LIST" || return 1
    [ -n "$host" ] && rm -f "$NGINX_DIR/certs/$host.crt" "$NGINX_DIR/certs/$host.key"
    nginx_apply || return 1
    echo "$folder ya no está en Nginx (su carpeta sigue igual)"
}

# nginx-puertos <http> <https>: los de Nginx (de 1024 en adelante: los de abajo son de root)
function nginx_ports() {
    local http=$1 https=$2 p
    for p in "$http" "$https"; do
        if ! [[ "$p" =~ ^[1-9][0-9]{3,4}$ ]] || [ "$p" -gt 65535 ]; then
            echo "Puerto no válido: $p (de 1024 a 65535)"
            return 1
        fi
    done
    [ "$http" == "$https" ] && { echo "http y https no pueden ir en el mismo puerto"; return 1; }
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] Nginx en los puertos $http y $https"; return 0; }
    if nginx_running; then
        for p in "$http" "$https"; do
            [ "$p" == "$(nginx_get HTTP)" ] || [ "$p" == "$(nginx_get HTTPS)" ] && continue
            nginx_port_free "$p" || { echo "El puerto $p ya lo usa otro programa"; return 1; }
        done
    fi
    mkdir -p -m 700 "$NGINX_DIR" || return 1
    ( umask 077; printf 'HTTP=%s\nHTTPS=%s\n' "$http" "$https" > "$NGINX_SETTINGS.nuevo" ) && mv -f "$NGINX_SETTINGS.nuevo" "$NGINX_SETTINGS" || return 1
    nginx_apply || return 1
    echo "Nginx en los puertos $http (http) y $https (https)"
}

# nginx-registro: lo último que ha dicho Nginx (sus errores)
function nginx_log() {
    if [ -s "$NGINX_ERROR_LOG" ]; then
        tail -200 "$NGINX_ERROR_LOG"
    else
        echo "Nginx no ha escrito nada en su registro ($NGINX_ERROR_LOG)"
    fi
}

# nginx-confiar: que el navegador acepte sin aviso el certificado de cada proyecto
function nginx_trust_all() {
    local folder root host n=0
    while IFS='|' read -r folder root; do
        host=$(nginx_host "$folder") || continue
        nginx_cert "$host" && nginx_trust "$host" && n=$((n + 1))
    done < <(nginx_projects)
    [ $n -eq 0 ] && echo "No hay proyectos en Nginx"
    return 0
}

# Para la ventana (gui-nginx):
#   N|instalado 1/0|versión instalada|la de este gestor|en marcha 1/0|http|https|PHP (ok, parado, sin-fpm)|encendido 1/0
#   P|carpeta|raíz|nombre|carpeta existe 1/0
#   C|carpeta          una de htdocs que aún no está en Nginx (para añadirla)
function gui_nginx() {
    local folder root d added=""
    printf 'N|%s|%s|%s|%s|%s|%s|%s|%s\n' "$(nginx_installed && echo 1 || echo 0)" "$(nginx_installed_version)" "$NGINX_VERSION" \
        "$(nginx_running && echo 1 || echo 0)" "$(nginx_get HTTP)" "$(nginx_get HTTPS)" "$(nginx_php_state)" "$(nginx_used && echo 1 || echo 0)"
    while IFS='|' read -r folder root; do
        printf 'P|%s|%s|%s|%s\n' "$folder" "$root" "$(nginx_host "$folder")" "$([ -d "$HTDOCS_DIR/$folder" ] && echo 1 || echo 0)"
        added+="|$folder|"
    done < <(nginx_projects)
    for d in "$HTDOCS_DIR"/*/; do
        d=${d%/}
        folder=${d##*/}
        [ -L "$d" ] && continue
        [[ "$folder" =~ ^[A-Za-z0-9_][A-Za-z0-9\ ._-]*$ ]] || continue
        [[ "$added" == *"|$folder|"* ]] && continue
        echo "C|$folder"
    done
    return 0
}

# nginx <orden> ...: las de la pestaña Nginx
function nginx_command() {
    case "$1" in
        nginx-usar) nginx_use "$2" ;;
        nginx-instalar) nginx_install ;;
        nginx-arrancar) nginx_start ;;
        nginx-parar) nginx_stop ;;
        nginx-reiniciar) nginx_stop > /dev/null; nginx_start ;;
        nginx-anadir) shift; nginx_add "$@" ;;
        nginx-quitar) nginx_remove "$2" ;;
        nginx-puertos) nginx_ports "$2" "$3" ;;
        nginx-registro) nginx_log ;;
        nginx-confiar) nginx_trust_all ;;
        *) echo "Uso: nexum nginx-usar si|no|nginx-instalar|nginx-arrancar|nginx-parar|nginx-reiniciar|nginx-anadir <carpeta> [subcarpeta]|nginx-quitar <carpeta>|nginx-puertos <http> <https>|nginx-registro|nginx-confiar"; return 1 ;;
    esac
}

# Tareas de la ventana (LVM_TAREA=1): lo que cambia algo pide la contraseña de administrador antes de
# empezar, no a mitad. Si se cancela, no se ha hecho nada (antes, lo hecho hasta el primer sudo se
# quedaba: el enlace de un proyecto al desmontarlo, por ejemplo). Lo que nunca la necesita, sin pedirla
if [ "${LVM_TAREA:-}" == 1 ]; then
    case "$1" in
        gui-*|node-*|exportar-bd|descargar-bd|exportar-proyecto|docker-registros|construir-pila|version|--version|-v|acerca|about|novedades|procesos|limpieza|copias-ficheros|manual|nginx-usar|nginx-arrancar|nginx-parar|nginx-reiniciar|nginx-anadir|nginx-quitar|nginx-puertos|nginx-registro|nginx-confiar) ;;
        # (el tunel, los repositorios y la rama de un proyecto, solo con tu usuario; borrar una BBDD, solo con el MariaDB en marcha)
        tunel-abrir|tunel-instalar|tunel-cerrar|repo-traer|rama-proyecto|borrar-bd|borrar-bd-marcadas|marcar-bd) ;;
        # (el administrador de pruebas: solo un ajuste de ~/.nexum)
        admin-pruebas) ;;
        # (Nginx: con tu usuario; instalarlo, solo si en Linux falta algun paquete para compilarlo)
        nginx-instalar) nginx_deps_missing && { sudo_first || exit 130; } ;;
        # (WP-CLI en las imagenes de PHP de Docker: un ajuste de ~/.nexum y las imagenes, con Docker Desktop)
        docker-wp-cli) ;;
        # (PostgreSQL y Nginx de Docker: Docker sin root y ficheros de ~/.nexum)
        docker-postgres) ;;
        # (la copia de las BBDD de Docker: Docker sin root (o Docker Desktop) y ~/nexum-backups)
        docker-copia) ;;
        docker-nginx) ;;
        # (confiar: el certificado va a tu llavero, y el Mac pide la contraseña en su propio aviso)
        docker-web) [ "$2" == confiar ] || { sudo_first || exit 130; } ;;
        # (importar-bd: solo si va a vaciar la cache de una tienda con ficheros de Apache)
        importar-bd) import_need_root "${@:4}" && { sudo_first || exit 130; } ;;
        # (copias: solo vaciar, y solo si hay copias de root que tu usuario no puede borrar)
        copias) [ "$2" == vaciar ] && copies_need_root && { sudo_first || exit 130; } ;;
        # (limpiar y limpiar-proyecto: solo si algo de lo que se va a limpiar es de root)
        limpiar) clean_need_root "${@:2}" && { sudo_first || exit 130; } ;;
        limpiar-proyecto) clean_project_need_root "${@:2}" && { sudo_first || exit 130; } ;;
        # (vhosts-sin-carpeta: solo quitar los cambia)
        vhosts-sin-carpeta) [ "$2" == quitar ] && { sudo_first || exit 130; } ;;
        *) sudo_first || exit 130 ;;
    esac
fi

